import {
  CONTACT_WINDOW_MS,
  PERFECT_WINDOW_MS,
  type PitchLocation,
  clamp,
  isInStrikeZone,
  zoneDistance,
} from "./Timeline.ts";

/**
 * SwingJudge — a pure function from (timing, location) to a contact verdict.
 *
 * Deliberately free of AudioContext, DOM, and clock access. Everything that could
 * be wrong about *when* the swing happened has already been resolved by the time
 * we get here; this file only decides what that timing is worth. That separation
 * is what makes the boundary behaviour cheap to test exhaustively.
 */

export type TimingBucket = "perfect" | "early" | "late" | "miss" | "take";

/** Quality tiers, ordered best to worst. Location can only move a swing down this list. */
export type ContactTier = "solid" | "weak" | "foul-tip" | "miss";

const TIER_ORDER: readonly ContactTier[] = ["solid", "weak", "foul-tip", "miss"];

export interface TimingWindows {
  perfectWindowMs: number;
  contactWindowMs: number;
}

export interface SwingJudgeInput {
  /** False when the batter took the pitch. */
  swung: boolean;
  /** Performance-clock ms of the keypress. Ignored when `swung` is false. */
  swingPerfMs: number;
  /** Performance-clock ms at which the ball was heard crossing the plate. */
  perceivedPlateMs: number;
  /** Measured hardware offset to subtract, from the calibration flow. */
  calibrationMs: number;
  location: PitchLocation;
  /** Override the default 30/70 ms windows (difficulty presets). */
  windows?: TimingWindows;
}

export interface SwingJudgment {
  swung: boolean;
  /** Signed error in ms. Negative is early, positive is late. 0 when taken. */
  deltaMs: number;
  timing: TimingBucket;
  /** 0..1 from timing alone, before location is considered. */
  timingScore: number;
  /** 0..1 from location alone — how much of the bat the batter could get on it. */
  plateCoverage: number;
  /** timingScore x plateCoverage. Drives exit velocity and commentary heat. */
  contactQuality: number;
  contact: ContactTier;
  /** Umpire's call on a taken pitch. Meaningless when `swung` is true. */
  inStrikeZone: boolean;
}

export function judgeSwing(input: SwingJudgeInput): SwingJudgment {
  const inStrikeZone = isInStrikeZone(input.location);
  const plateCoverage = computePlateCoverage(input.location);

  if (!input.swung) {
    return {
      swung: false,
      deltaMs: 0,
      timing: "take",
      timingScore: 0,
      plateCoverage,
      contactQuality: 0,
      contact: "miss",
      inStrikeZone,
    };
  }

  const deltaMs = input.swingPerfMs - input.perceivedPlateMs - input.calibrationMs;
  const magnitude = Math.abs(deltaMs);
  const perfectMs = input.windows?.perfectWindowMs ?? PERFECT_WINDOW_MS;
  const contactMs = input.windows?.contactWindowMs ?? CONTACT_WINDOW_MS;

  const timing: TimingBucket =
    magnitude < perfectMs ? "perfect" : magnitude <= contactMs ? (deltaMs < 0 ? "early" : "late") : "miss";

  const timingScore = computeTimingScore(magnitude, perfectMs, contactMs);

  // Two-stage resolution. The timing bucket sets the ceiling exactly as the spec
  // describes, then location is allowed to pull it down — never to push it up.
  // A batter who guesses the timing perfectly on a pitch off the plate has still
  // guessed perfectly; he just can't reach it.
  const base: ContactTier = timing === "perfect" ? "solid" : timing === "miss" ? "miss" : "weak";
  const contact = downgrade(base, coverageDowngradeSteps(plateCoverage));

  return {
    swung: true,
    deltaMs,
    timing,
    timingScore,
    plateCoverage,
    contactQuality: timingScore * plateCoverage,
    contact,
    inStrikeZone,
  };
}

/**
 * Continuous 0..1 score from timing error, piecewise so that the two spec
 * thresholds land on clean values (0.85 at 30 ms, 0.35 at 70 ms).
 */
function computeTimingScore(magnitudeMs: number, perfectMs: number, contactMs: number): number {
  if (magnitudeMs >= contactMs) return 0;
  if (magnitudeMs < perfectMs) {
    return 1 - (magnitudeMs / perfectMs) * 0.15;
  }
  const span = Math.max(contactMs - perfectMs, 1);
  const t = (magnitudeMs - perfectMs) / span;
  return 0.85 - t * 0.5;
}

/**
 * How much bat the batter can get on a pitch at this location, 0..1.
 *
 * Gentle inside the zone (the black is still very hittable at 0.85), then a steep
 * fall once the ball is genuinely off the plate. Beyond two zone-widths out it
 * bottoms out rather than reaching zero, because the occasional golf shot at a
 * ball in the other batter's box is part of baseball.
 */
export function computePlateCoverage(location: PitchLocation): number {
  const distance = zoneDistance(location);
  if (distance <= 1) return 1 - 0.15 * distance;
  if (distance <= 2) return clamp(0.85 - 0.75 * (distance - 1), 0.1, 0.85);
  return 0.05;
}

function coverageDowngradeSteps(coverage: number): number {
  if (coverage >= 0.7) return 0;
  if (coverage >= 0.4) return 1;
  if (coverage >= 0.2) return 2;
  return 3;
}

function downgrade(tier: ContactTier, steps: number): ContactTier {
  const index = TIER_ORDER.indexOf(tier);
  const next = Math.min(TIER_ORDER.length - 1, index + steps);
  return TIER_ORDER[next] as ContactTier;
}

/** True when the swing produced any bat-on-ball sound at all. */
export function madeContact(judgment: SwingJudgment): boolean {
  return judgment.swung && judgment.contact !== "miss";
}
