/**
 * Player — roster identity + ability ratings (1–99).
 *
 * Ratings are a baked snapshot from MLB season stats (see Teams.ts header),
 * not live game box-score lines.
 */

export type Hand = "L" | "R" | "S";
export type BatterHand = "L" | "R";

export interface BatterRatings {
  /** Contact / bat-to-ball — timing windows + AI sigma. */
  readonly contact: number;
  /** Plate discipline — AI zone swing / chase. */
  readonly eye: number;
  /** Extra-base / HR tendency on solid contact. */
  readonly power: number;
  /** Baserunning aggression on hits. */
  readonly speed: number;
}

export interface PitcherRatings {
  /** Fastball velo proxy → profile velocityMph / flight. */
  readonly velocity: number;
  /** Location scatter (higher = tighter). */
  readonly command: number;
  /** Miss / K stuff → offspeed bias + AI early-bias on offspeed. */
  readonly stuff: number;
}

export interface Player {
  readonly id: number;
  /** Radio-friendly surname shown on scoreboard / commentary. */
  readonly name: string;
  readonly fullName: string;
  readonly bats: Hand;
  readonly throws: Hand;
  readonly batter?: BatterRatings;
  readonly pitcher?: PitcherRatings;
}

/** Switch hitters bat opposite the pitcher's throwing hand. */
export function resolveBatterHand(bats: Hand, pitcherThrows: Hand): BatterHand {
  if (bats === "S") return pitcherThrows === "L" ? "R" : "L";
  return bats;
}

export function clampRating(n: number): number {
  return Math.max(40, Math.min(95, Math.round(n)));
}

/** Map 40–95 rating onto a multiplier centered at 70 ≈ 1.0. */
export function ratingFactor(rating: number, strength = 0.35): number {
  const t = (rating - 70) / 30; // −1 .. ~0.83
  return 1 + t * strength;
}
