import type { AudioEngine, BusName } from "../audio/AudioEngine.ts";
import type { AnnounceMode } from "../ui/Prefs.ts";
import type { RadioLog } from "../ui/RadioLog.ts";
import type { SampledVoiceBackend } from "./SampledVoiceBackend.ts";
import type { SpeechVoiceBackend } from "./SpeechVoiceBackend.ts";
import {
  estimateSpokenSeconds,
  type Phrase,
  type SpeakHandle,
  type Speaker,
  type VoiceBackend,
} from "./VoiceBackend.ts";

/**
 * CastVoiceBackend — live Adam / Brian / Eric via `/api/booth/tts`.
 *
 * Speaks the real phrase text (batter names, count, spray) so the booth matches
 * the situation. Falls back to directed sample bank, then OS speech.
 */

export interface CastVoiceBackendOptions {
  engine: AudioEngine;
  log: RadioLog;
  samples: SampledVoiceBackend;
  speech: SpeechVoiceBackend;
  getAnnounceMode: () => AnnounceMode;
  /** Defaults to same-origin `/api/booth/tts`. */
  ttsUrl?: string;
}

type CacheEntry = { buffer: AudioBuffer; durationSec: number };

export class CastVoiceBackend implements VoiceBackend {
  private readonly engine: AudioEngine;
  private readonly log: RadioLog;
  private readonly samples: SampledVoiceBackend;
  private readonly speech: SpeechVoiceBackend;
  private readonly getAnnounceMode: () => AnnounceMode;
  private readonly ttsUrl: string;
  private readonly cache = new Map<string, CacheEntry>();
  private readonly inflight = new Map<string, Promise<AudioBuffer | null>>();
  private apiAvailable: boolean | null = null;

  constructor(options: CastVoiceBackendOptions) {
    this.engine = options.engine;
    this.log = options.log;
    this.samples = options.samples;
    this.speech = options.speech;
    this.getAnnounceMode = options.getAnnounceMode;
    this.ttsUrl = options.ttsUrl ?? "/api/booth/tts";
  }

  async warmUp(): Promise<void> {
    try {
      const res = await fetch("/api/booth/health", { cache: "no-store" });
      if (!res.ok) {
        this.apiAvailable = false;
        return;
      }
      const body = (await res.json()) as { ok?: boolean };
      this.apiAvailable = body.ok === true;
    } catch {
      this.apiAvailable = false;
    }
  }

  estimateDuration(phrase: Phrase): number {
    const key = cacheKey(phrase);
    const hit = this.cache.get(key);
    if (hit) return hit.durationSec + 0.05;
    return estimateSpokenSeconds(phrase.text, phrase.energy) * 1.35 + 0.35;
  }

  speak(phrase: Phrase, atContextTime: number): SpeakHandle {
    const mode = this.getAnnounceMode();
    const speakAloud = shouldSpeakAloud(phrase) && mode !== "screen-reader";

    if (!speakAloud || phrase.speaker === "umpire") {
      return this.speech.speak(phrase, atContextTime);
    }

    // Kick fetch early so audio is warm when the clock fires.
    const audioPromise = this.ensureAudio(phrase);
    const durationSec = this.estimateDuration(phrase);
    this.engine.duckFor(atContextTime, durationSec);

    const perfTarget = this.engine.clock.audioToPerf(atContextTime);
    const delayMs = Math.max(0, perfTarget - performance.now());

    let cancelled = false;
    let voice: { stop: (when?: number) => void } | null = null;
    let fallbackHandle: SpeakHandle | null = null;

    const timer = setTimeout(() => {
      void (async () => {
        if (cancelled) return;
        try {
          const buffer = await audioPromise;
          if (cancelled) return;
          if (buffer) {
            this.log.append(phrase);
            const bus: BusName =
              phrase.speaker === "color" || phrase.speaker === "utility" ? "color" : "announcer";
            voice = playBuffer(this.engine, buffer, {
              bus,
              at: this.engine.currentTime,
              gain: boothGain(phrase),
              playbackRate: boothRate(phrase),
            });
            return;
          }
        } catch {
          /* fall through */
        }
        if (cancelled) return;
        // Samples / speech append the log themselves.
        fallbackHandle =
          this.samples.loadedClipCount > 0
            ? this.samples.speak(phrase, this.engine.currentTime)
            : this.speech.speak(phrase, this.engine.currentTime);
      })();
    }, delayMs);

    return {
      durationSec,
      cancel: () => {
        cancelled = true;
        clearTimeout(timer);
        voice?.stop();
        fallbackHandle?.cancel();
      },
    };
  }

  private ensureAudio(phrase: Phrase): Promise<AudioBuffer | null> {
    if (this.apiAvailable === false) return Promise.resolve(null);
    const key = cacheKey(phrase);
    const cached = this.cache.get(key);
    if (cached) return Promise.resolve(cached.buffer);

    const existing = this.inflight.get(key);
    if (existing) return existing;

    const pending = this.fetchAudio(phrase, key).finally(() => {
      this.inflight.delete(key);
    });
    this.inflight.set(key, pending);
    return pending;
  }

  private async fetchAudio(phrase: Phrase, key: string): Promise<AudioBuffer | null> {
    try {
      const res = await fetch(this.ttsUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        cache: "no-store",
        body: JSON.stringify({
          text: phrase.text,
          speaker: castSpeaker(phrase.speaker),
          tone: phrase.tone ?? "calm",
        }),
      });
      if (!res.ok) {
        if (res.status === 503) this.apiAvailable = false;
        return null;
      }
      this.apiAvailable = true;
      const raw = await res.arrayBuffer();
      const buffer = await this.engine.ctx.decodeAudioData(raw.slice(0));
      this.cache.set(key, { buffer, durationSec: buffer.duration });
      return buffer;
    } catch {
      return null;
    }
  }
}

function castSpeaker(speaker: Speaker): "announcer" | "color" | "utility" {
  if (speaker === "color") return "color";
  if (speaker === "utility") return "utility";
  return "announcer";
}

function cacheKey(phrase: Phrase): string {
  return `${castSpeaker(phrase.speaker)}|${phrase.tone ?? "calm"}|${phrase.text}`;
}

function shouldSpeakAloud(phrase: Phrase): boolean {
  return !phrase.id.startsWith("action.");
}

function boothGain(phrase: Phrase): number {
  // Brian (color) renders quieter than Adam at the same settings — lift the clip.
  let base = 1.15;
  if (phrase.speaker === "color") base = 1.45;
  else if (phrase.speaker === "utility") base = 1.2;
  return base + phrase.energy * 0.22;
}

function boothRate(phrase: Phrase): number {
  return 1 + Math.max(0, phrase.energy - 0.5) * 0.03;
}

function playBuffer(
  engine: AudioEngine,
  buffer: AudioBuffer,
  options: { bus: BusName; at: number; gain: number; playbackRate: number },
): { stop: (when?: number) => void } {
  const { ctx } = engine;
  const at = Math.max(options.at, ctx.currentTime);
  const source = ctx.createBufferSource();
  source.buffer = buffer;
  source.playbackRate.value = options.playbackRate;
  const gain = ctx.createGain();
  gain.gain.value = options.gain;
  source.connect(gain);
  gain.connect(engine.busInput(options.bus));
  try {
    source.start(at);
  } catch {
    /* ignore */
  }
  return {
    stop(when?: number): void {
      const t = Math.max(when ?? ctx.currentTime, ctx.currentTime);
      try {
        gain.gain.cancelScheduledValues(t);
        gain.gain.setValueAtTime(Math.max(gain.gain.value, 0), t);
        gain.gain.linearRampToValueAtTime(0, t + 0.06);
        source.stop(t + 0.08);
      } catch {
        /* already stopped */
      }
    },
  };
}
