export interface EndGameCardModel {
  won: boolean;
  playerRuns: number;
  opponentRuns: number;
  innings: number;
  timingSummary: string;
  modeLabel: string;
  /** Override title (e.g. "Season complete", "Series win!"). */
  titleOverride?: string;
  /** Campaign line under the score — series clinch / standings beat. */
  seriesSummary?: string;
  /** Primary CTA label — "New Game", "New Series", "Next game", … */
  primaryLabel?: string;
}

export type EndGameCardAction = "new" | "difficulty" | "feedback" | "share";

/**
 * Clear post-game surface with next-action CTAs.
 */
export class EndGameCard {
  private readonly root: HTMLElement;
  private readonly title: HTMLElement;
  private readonly score: HTMLElement;
  private readonly timing: HTMLElement;
  private readonly mode: HTMLElement;
  private readonly series: HTMLElement;
  private readonly newButton: HTMLButtonElement;

  constructor(root: HTMLElement) {
    this.root = root;
    this.root.className = "end-card";
    this.root.hidden = true;
    this.root.setAttribute("role", "dialog");
    this.root.setAttribute("aria-modal", "true");

    this.title = document.createElement("h2");
    this.title.className = "end-card-title";
    this.title.id = "end-card-title";
    this.title.tabIndex = -1;
    this.root.setAttribute("aria-labelledby", "end-card-title");

    this.score = document.createElement("p");
    this.score.className = "end-card-score";
    this.timing = document.createElement("p");
    this.timing.className = "end-card-timing";
    this.mode = document.createElement("p");
    this.mode.className = "end-card-mode";
    this.series = document.createElement("p");
    this.series.className = "end-card-series";

    const actions = document.createElement("div");
    actions.className = "end-card-actions";
    actions.innerHTML = `
      <button type="button" class="primary" data-end-action="new">New Game</button>
      <button type="button" class="secondary" data-end-action="share">Share this broadcast</button>
      <button type="button" class="secondary" data-end-action="difficulty">Change difficulty</button>
      <button type="button" class="secondary" data-end-action="feedback">Feedback</button>
    `;
    this.newButton = actions.querySelector("[data-end-action='new']") as HTMLButtonElement;

    this.root.replaceChildren(
      this.title,
      this.score,
      this.series,
      this.timing,
      this.mode,
      actions,
    );
  }

  show(model: EndGameCardModel): void {
    if (model.titleOverride) {
      this.title.textContent = model.titleOverride;
    } else if (model.seriesSummary) {
      this.title.textContent = model.won ? "Series win!" : "Series over";
    } else {
      this.title.textContent =
        model.won ? "You win!" : model.playerRuns === model.opponentRuns ? "Final" : "Ballgame";
    }
    if (model.seriesSummary) {
      this.series.textContent = model.seriesSummary;
      this.series.hidden = false;
    } else {
      this.series.textContent = "";
      this.series.hidden = true;
    }
    this.score.textContent = `Final: ${model.playerRuns} – ${model.opponentRuns} (${model.innings} inn.)`;
    this.timing.textContent = model.timingSummary;
    this.mode.textContent = model.modeLabel;
    this.newButton.textContent =
      model.primaryLabel ?? (model.seriesSummary ? "New Series" : "New Game");
    this.root.hidden = false;
    queueMicrotask(() => this.newButton.focus());
  }

  hide(): void {
    this.root.hidden = true;
  }

  onAction(handler: (action: EndGameCardAction) => void): void {
    this.root.addEventListener("click", (event) => {
      const target = event.target;
      if (!(target instanceof HTMLElement)) return;
      const action = target.getAttribute("data-end-action");
      if (
        action === "new" ||
        action === "difficulty" ||
        action === "feedback" ||
        action === "share"
      ) {
        handler(action);
      }
    });
  }
}
