import type { AudioEngine } from "../audio/AudioEngine.ts";
import { playWindup, WINDUP_SECONDS } from "../audio/voices/windup.ts";
import { playPitchFlight } from "../audio/voices/pitchFlight.ts";
import { playBatContact } from "../audio/voices/batContact.ts";
import { playGlovePop } from "../audio/voices/glovePop.ts";
import { playPlateTick } from "../audio/voices/plateTick.ts";
import type { DifficultyConfig } from "../game/Difficulty.ts";
import { speakNow, cancelSpeech } from "../commentary/speech.ts";
import { judgeSwing, type SwingJudgment } from "./SwingJudge.ts";
import {
  applyReleaseDrift,
  applyReleaseFlightTweak,
  judgeRelease,
  type ReleaseJudgment,
} from "./ReleaseJudge.ts";
import type { SwingEvent, SwingInput } from "./SwingInput.ts";
import {
  CONTACT_WINDOW_MS,
  PERFECT_WINDOW_MS,
  RESOLVE_DELAY_SEC,
  SWING_WINDOW_MS,
  type PitchLocation,
  type PitchProfile,
  type PitchTimeline,
} from "./Timeline.ts";

/**
 * PitchSequencer — throws one pitch and reports what happened.
 *
 * Batter mode: SPACE vs plate (beat 5). Pitcher mode: SPACE vs release (beat 4),
 * then flight is scheduled to the drifted location.
 */

const LEAD_IN_SEC = 0.12;
const SCHEDULE_EPSILON_SEC = 0.008;
const GLOVE_DELAY_SEC = 0.012;
const FOLLOW_UP_DELAY_SEC = 0.32;

export interface PitchResult {
  timeline: PitchTimeline;
  judgment: SwingJudgment;
  perceivedPlateMs: number;
  contactTime: number;
  followUpTime: number;
  taken: boolean;
}

export interface PitcherResult {
  timeline: PitchTimeline;
  release: ReleaseJudgment;
  finalLocation: PitchLocation;
  finalProfile: PitchProfile;
  perceivedPlateMs: number;
  contactTime: number;
  followUpTime: number;
  /** Cut the flight tone early when the bat gets to the ball. */
  cutFlight: (time: number) => void;
}

export interface PitchSequencerOptions {
  engine: AudioEngine;
  input: SwingInput;
  getCalibrationMs: () => number;
  /** Active difficulty — read fresh each pitch so mid-game changes apply. */
  getDifficulty: () => DifficultyConfig;
  /** Optional RNG for release drift (tests). */
  rng?: () => number;
  /** Live-region / SR cue at swing or release time (in addition to optional TTS). */
  onTimingCue?: (text: "swing" | "release") => void;
  /** When false, skip Web Speech for the timing cue (screen-reader mode). Default true. */
  shouldSpeakTimingCue?: () => boolean;
}

export class PitchSequencer {
  private readonly engine: AudioEngine;
  private readonly input: SwingInput;
  private readonly getCalibrationMs: () => number;
  private readonly getDifficulty: () => DifficultyConfig;
  private readonly rng: () => number;
  private readonly onTimingCue: ((text: "swing" | "release") => void) | null;
  private readonly shouldSpeakTimingCue: () => boolean;

  private nextId = 1;
  private tick: ReturnType<typeof setInterval> | null = null;
  private active: ActiveBatter | ActivePitcher | null = null;

  constructor(options: PitchSequencerOptions) {
    this.engine = options.engine;
    this.input = options.input;
    this.getCalibrationMs = options.getCalibrationMs;
    this.getDifficulty = options.getDifficulty;
    this.rng = options.rng ?? Math.random;
    this.onTimingCue = options.onTimingCue ?? null;
    this.shouldSpeakTimingCue = options.shouldSpeakTimingCue ?? (() => true);
  }

  get isPitchInFlight(): boolean {
    return this.active !== null;
  }

  throwPitch(
    profile: PitchProfile,
    location: PitchLocation,
    hooks?: {
      onScheduled?: (timeline: PitchTimeline) => void;
      /** Override difficulty windows (e.g. batter contact rating). */
      windows?: { perfectWindowMs: number; contactWindowMs: number };
    },
  ): Promise<PitchResult> {
    if (this.active) return Promise.reject(new Error("A pitch is already in flight"));

    const { engine } = this;
    const ctx = engine.ctx;
    const difficulty = this.getDifficulty();

    const startTime = ctx.currentTime + LEAD_IN_SEC;
    const releaseTime = startTime + WINDUP_SECONDS;
    const plateTime = releaseTime + profile.flightSeconds;
    const resolveTime = plateTime + RESOLVE_DELAY_SEC;

    engine.clock.sample();
    const timeline: PitchTimeline = {
      id: this.nextId++,
      profile,
      location,
      startTime,
      releaseTime,
      plateTime,
      resolveTime,
      perceivedPlateMs: engine.clock.audioToPerf(plateTime),
    };

    engine.focusOnField(startTime, plateTime - startTime + 0.25);

    playWindup(engine, startTime, { countableBeats: difficulty.countableBeats });
    const flight = playPitchFlight(engine, profile, location, releaseTime, plateTime);

    if (difficulty.plateTick) {
      playPlateTick(engine, plateTime);
    }

    let speechToken = -1;
    let speechTimer: ReturnType<typeof setTimeout> | null = null;
    if (difficulty.spokenSwing) {
      const delayMs = Math.max(0, timeline.perceivedPlateMs - performance.now());
      speechTimer = setTimeout(() => {
        speechTimer = null;
        this.onTimingCue?.("swing");
        if (this.shouldSpeakTimingCue()) {
          speechToken = speakNow({ text: "swing", speaker: "umpire", energy: 0.9 });
        }
      }, delayMs);
    }

    const clearSpeech = (): void => {
      if (speechTimer !== null) {
        clearTimeout(speechTimer);
        speechTimer = null;
      }
      cancelSpeech(speechToken);
      speechToken = -1;
    };

    return new Promise<PitchResult>((resolve, reject) => {
      const active: ActiveBatter = {
        kind: "batter",
        timeline,
        flight,
        resolve,
        reject,
        disarm: () => {},
        clearSpeech,
        windows: hooks?.windows ?? {
          perfectWindowMs: difficulty.perfectWindowMs,
          contactWindowMs: difficulty.contactWindowMs,
        },
      };
      this.active = active;

      const onSwing = (event: SwingEvent): void => {
        const reference = this.audioToPerf(timeline.plateTime);
        if (event.perfMs < reference - SWING_WINDOW_MS) {
          active.disarm = this.input.arm(onSwing);
          return;
        }
        this.finishBatter(active, event.perfMs);
      };

      active.disarm = this.input.arm(onSwing);
      this.startTicking();
      hooks?.onScheduled?.(timeline);
    });
  }

  /**
   * Human pitcher: windup, SPACE on release, then flight to the drifted spot.
   * Batter contact SFX are left to the caller after BatterAI decides.
   */
  throwPitchAsPitcher(
    profile: PitchProfile,
    intendedLocation: PitchLocation,
    hooks?: { onScheduled?: (timeline: PitchTimeline) => void },
  ): Promise<PitcherResult> {
    if (this.active) return Promise.reject(new Error("A pitch is already in flight"));

    const { engine } = this;
    const ctx = engine.ctx;
    const difficulty = this.getDifficulty();

    const startTime = ctx.currentTime + LEAD_IN_SEC;
    const releaseTime = startTime + WINDUP_SECONDS;
    // Placeholder plate — rewritten once release quality sets the final profile.
    const plateTime = releaseTime + profile.flightSeconds;
    const resolveTime = releaseTime + SWING_WINDOW_MS / 1000 + 0.05;

    engine.clock.sample();
    const timeline: PitchTimeline = {
      id: this.nextId++,
      profile,
      location: intendedLocation,
      startTime,
      releaseTime,
      plateTime,
      resolveTime,
      perceivedPlateMs: engine.clock.audioToPerf(plateTime),
    };

    // Cover windup + a long flight bound; refined when the ball leaves the hand.
    engine.focusOnField(startTime, WINDUP_SECONDS + 1.2);

    playWindup(engine, startTime, { countableBeats: difficulty.countableBeats });

    let speechToken = -1;
    let speechTimer: ReturnType<typeof setTimeout> | null = null;
    if (difficulty.spokenSwing) {
      const delayMs = Math.max(0, engine.clock.audioToPerf(releaseTime) - performance.now());
      speechTimer = setTimeout(() => {
        speechTimer = null;
        this.onTimingCue?.("release");
        if (this.shouldSpeakTimingCue()) {
          speechToken = speakNow({ text: "release", speaker: "umpire", energy: 0.9 });
        }
      }, delayMs);
    }

    const clearSpeech = (): void => {
      if (speechTimer !== null) {
        clearTimeout(speechTimer);
        speechTimer = null;
      }
      cancelSpeech(speechToken);
      speechToken = -1;
    };

    return new Promise<PitcherResult>((resolve, reject) => {
      const active: ActivePitcher = {
        kind: "pitcher",
        phase: "windup",
        timeline,
        intendedProfile: profile,
        intendedLocation,
        flight: null,
        resolve,
        reject,
        disarm: () => {},
        clearSpeech,
        windows: {
          perfectWindowMs: difficulty.perfectWindowMs,
          contactWindowMs: difficulty.contactWindowMs,
        },
      };
      this.active = active;

      const onRelease = (event: SwingEvent): void => {
        const reference = this.audioToPerf(active.timeline.releaseTime);
        if (event.perfMs < reference - SWING_WINDOW_MS) {
          active.disarm = this.input.arm(onRelease);
          return;
        }
        this.resolvePitcherRelease(active, event.perfMs, false);
      };

      active.disarm = this.input.arm(onRelease);
      this.startTicking();
      hooks?.onScheduled?.(timeline);
    });
  }

  cancel(): void {
    const active = this.active;
    if (!active) return;
    active.disarm();
    active.clearSpeech();
    this.active = null;
    this.stopTicking();
    active.flight?.cutAt(this.engine.ctx.currentTime);
    active.reject(new Error("Pitch cancelled"));
  }

  private audioToPerf(audioTime: number): number {
    this.engine.clock.sample();
    return this.engine.clock.audioToPerf(audioTime);
  }

  private startTicking(): void {
    if (this.tick !== null) return;
    this.tick = setInterval(() => {
      const active = this.active;
      if (!active) {
        this.stopTicking();
        return;
      }
      if (active.kind === "batter") {
        if (this.engine.ctx.currentTime >= active.timeline.resolveTime) {
          this.finishBatter(active, null);
        }
        return;
      }
      if (active.phase === "windup") {
        if (this.engine.ctx.currentTime >= active.timeline.resolveTime) {
          this.resolvePitcherRelease(active, null, true);
        }
        return;
      }
      if (this.engine.ctx.currentTime >= active.timeline.resolveTime) {
        this.finishPitcher(active);
      }
    }, 10);
  }

  private stopTicking(): void {
    if (this.tick === null) return;
    clearInterval(this.tick);
    this.tick = null;
  }

  private resolvePitcherRelease(
    active: ActivePitcher,
    releasePerfMs: number | null,
    autoReleased: boolean,
  ): void {
    if (this.active !== active || active.phase !== "windup") return;

    active.disarm();
    active.clearSpeech();

    const perceivedReleaseMs = this.audioToPerf(active.timeline.releaseTime);
    const calibrationMs = this.getCalibrationMs();
    let deltaMs: number;
    if (releasePerfMs === null) {
      deltaMs = active.windows.contactWindowMs + 40;
      autoReleased = true;
    } else {
      deltaMs = releasePerfMs - perceivedReleaseMs - calibrationMs;
    }

    const release = judgeRelease(deltaMs, active.windows, autoReleased);
    const finalLocation = applyReleaseDrift(active.intendedLocation, release, this.rng);
    const finalProfile = applyReleaseFlightTweak(active.intendedProfile, release);

    const ctx = this.engine.ctx;
    const actualRelease = Math.max(active.timeline.releaseTime, ctx.currentTime + SCHEDULE_EPSILON_SEC);
    const plateTime = actualRelease + finalProfile.flightSeconds;
    const resolveTime = plateTime + RESOLVE_DELAY_SEC;

    this.engine.clock.sample();
    const timeline: PitchTimeline = {
      ...active.timeline,
      profile: finalProfile,
      location: finalLocation,
      releaseTime: actualRelease,
      plateTime,
      resolveTime,
      perceivedPlateMs: this.engine.clock.audioToPerf(plateTime),
    };

    active.timeline = timeline;
    active.release = release;
    active.finalLocation = finalLocation;
    active.finalProfile = finalProfile;
    active.phase = "flight";

    this.engine.focusOnField(actualRelease, finalProfile.flightSeconds + 0.35);
    active.flight = playPitchFlight(
      this.engine,
      finalProfile,
      finalLocation,
      actualRelease,
      plateTime,
    );
  }

  private finishPitcher(active: ActivePitcher): void {
    if (this.active !== active || active.phase !== "flight" || !active.release) return;
    this.active = null;
    this.stopTicking();

    const ctx = this.engine.ctx;
    const contactTime = Math.max(active.timeline.plateTime, ctx.currentTime + SCHEDULE_EPSILON_SEC);
    const perceivedPlateMs = this.audioToPerf(active.timeline.plateTime);

    const flight = active.flight;
    active.resolve({
      timeline: active.timeline,
      release: active.release,
      finalLocation: active.finalLocation ?? active.timeline.location,
      finalProfile: active.finalProfile ?? active.timeline.profile,
      perceivedPlateMs,
      contactTime,
      followUpTime: Math.max(contactTime + FOLLOW_UP_DELAY_SEC, ctx.currentTime + SCHEDULE_EPSILON_SEC),
      cutFlight: (time: number) => flight?.cutAt(time),
    });
  }

  private finishBatter(active: ActiveBatter, swingPerfMs: number | null): void {
    if (this.active !== active) return;
    this.active = null;
    active.disarm();
    this.stopTicking();
    if (swingPerfMs !== null) active.clearSpeech();

    const { engine } = this;
    const ctx = engine.ctx;
    const { timeline } = active;
    const perceivedPlateMs = this.audioToPerf(timeline.plateTime);

    const judgment = judgeSwing({
      swung: swingPerfMs !== null,
      swingPerfMs: swingPerfMs ?? 0,
      perceivedPlateMs,
      calibrationMs: this.getCalibrationMs(),
      location: timeline.location,
      windows: active.windows,
    });

    const contactTime = Math.max(timeline.plateTime, ctx.currentTime + SCHEDULE_EPSILON_SEC);

    if (judgment.swung) {
      playBatContact(engine, {
        at: contactTime,
        tier: judgment.contact,
        quality: judgment.contactQuality,
        spray: clampSpray(-judgment.deltaMs / 70),
      });
    }

    const reachesMitt = !judgment.swung || judgment.contact === "miss" || judgment.contact === "foul-tip";
    if (reachesMitt) {
      playGlovePop(engine, contactTime + GLOVE_DELAY_SEC, timeline.profile.velocityMph);
    } else {
      active.flight.cutAt(contactTime);
    }

    active.resolve({
      timeline,
      judgment,
      perceivedPlateMs,
      contactTime,
      followUpTime: Math.max(contactTime + FOLLOW_UP_DELAY_SEC, ctx.currentTime + SCHEDULE_EPSILON_SEC),
      taken: swingPerfMs === null,
    });
  }
}

interface ActiveBatter {
  kind: "batter";
  timeline: PitchTimeline;
  flight: { cutAt(time: number): void };
  resolve: (result: PitchResult) => void;
  reject: (reason: Error) => void;
  disarm: () => void;
  clearSpeech: () => void;
  windows: { perfectWindowMs: number; contactWindowMs: number };
}

interface ActivePitcher {
  kind: "pitcher";
  phase: "windup" | "flight";
  timeline: PitchTimeline;
  intendedProfile: PitchProfile;
  intendedLocation: PitchLocation;
  flight: { cutAt(time: number): void } | null;
  resolve: (result: PitcherResult) => void;
  reject: (reason: Error) => void;
  disarm: () => void;
  clearSpeech: () => void;
  windows: { perfectWindowMs: number; contactWindowMs: number };
  release?: ReleaseJudgment;
  finalLocation?: PitchLocation;
  finalProfile?: PitchProfile;
}

function clampSpray(value: number): number {
  return Math.min(1, Math.max(-1, value));
}

/** Defaults used when a caller has no difficulty context (tests, harness). */
export const DEFAULT_WINDOWS = {
  perfectWindowMs: PERFECT_WINDOW_MS,
  contactWindowMs: CONTACT_WINDOW_MS,
} as const;

/** Play contact / mitt SFX after BatterAI decides (pitcher path). */
export function playPitchAftermath(
  engine: AudioEngine,
  judgment: SwingJudgment,
  contactTime: number,
  velocityMph: number,
  cutFlight: (time: number) => void,
): void {
  if (judgment.swung) {
    playBatContact(engine, {
      at: contactTime,
      tier: judgment.contact,
      quality: judgment.contactQuality,
      spray: clampSpray(-judgment.deltaMs / 70),
    });
  }
  const reachesMitt = !judgment.swung || judgment.contact === "miss" || judgment.contact === "foul-tip";
  if (reachesMitt) {
    playGlovePop(engine, contactTime + GLOVE_DELAY_SEC, velocityMph);
  } else {
    cutFlight(contactTime);
  }
}
