import { isHighLeverage } from "../game/Leverage.ts";
import type { PlateOutcome } from "../game/GameState.ts";
import type { PlayResult } from "../game/OutcomeResolver.ts";
import type { ContactTier } from "../timing/SwingJudge.ts";
import type { DeliveryTone, Phrase } from "./VoiceBackend.ts";

/**
 * Map game heat → booth performance tone.
 *
 * Energy alone cannot express frustration vs celebration; tone selects which
 * acted take a SampledVoiceBackend should load.
 */

export interface TonePlayInput {
  result: PlayResult;
  runsScored: number;
  leverage: number;
  gameOver: boolean;
  outcomeKind: PlateOutcome["kind"];
  swung: boolean;
  contact: ContactTier | "none";
}

export function toneForPlay(ctx: TonePlayInput): DeliveryTone {
  const highLev = isHighLeverage(ctx.leverage);
  const runs = ctx.runsScored;
  const walkOff = ctx.gameOver && runs > 0;

  if (ctx.result === "home-run" || walkOff) return "hot";
  if (runs > 0 && highLev) return "hot";
  if (runs > 0) return "lift";

  if (ctx.outcomeKind === "strikeout") return highLev ? "hot" : "lift";

  if (ctx.result === "double" || ctx.result === "single") return highLev ? "lift" : "calm";

  if (
    (ctx.result === "ground-out" ||
      ctx.result === "pop-up" ||
      ctx.result === "fly-out" ||
      ctx.result === "line-out") &&
    highLev &&
    ctx.swung &&
    (ctx.contact === "weak" || ctx.contact === "foul-tip")
  ) {
    return "wry";
  }

  if (ctx.result === "swinging-strike" || ctx.result === "called-strike") return "calm";
  if (ctx.result === "ball" || ctx.result === "foul-ball") return "calm";

  return "calm";
}

export function toneForColorLine(fragmentBaseId: string): DeliveryTone {
  if (
    fragmentBaseId.startsWith("color.chase") ||
    fragmentBaseId.startsWith("color.taken-cookie") ||
    fragmentBaseId.startsWith("color.early") ||
    fragmentBaseId.startsWith("color.late")
  ) {
    return "wry";
  }
  if (fragmentBaseId.startsWith("color.barrel") || fragmentBaseId.startsWith("color.tension")) {
    return "lift";
  }
  // bridge.color / bridge.pa-color / color.filler / color.good-take → calm Brian
  return "calm";
}

/** Infer a coarse tone from energy when a phrase omitted an explicit tone. */
export function toneFromEnergy(energy: number): DeliveryTone {
  if (energy >= 0.85) return "hot";
  if (energy >= 0.55) return "lift";
  return "calm";
}

export function effectiveTone(phrase: Phrase): DeliveryTone {
  return phrase.tone ?? toneFromEnergy(phrase.energy);
}

/**
 * Stable sample key: fragment clipId + tone.
 * Fallback order lets a sparse bank still cover hot moments with lift/calm takes.
 *
 * Variant fallback: phrase text may roll `call.foul.2` while the bank only ships
 * `call.foul.0` — without collapsing to `.0`, almost every multi-line family
 * misses and falls through to system TTS.
 */
export function clipLookupCandidates(phrase: Phrase): string[] {
  const tone = effectiveTone(phrase);
  const chain = toneFallbackChain(tone);
  const keys: string[] = [];
  for (const base of clipIdBaseFallbacks(phrase.clipId ?? phrase.id)) {
    for (const t of chain) keys.push(`${base}__${t}`);
  }
  return keys;
}

/** `call.foul.2` → [`call.foul.2`, `call.foul.0`] (deduped). */
export function clipIdBaseFallbacks(clipId: string): string[] {
  const bases = [clipId];
  const dotted = clipId.match(/^(.*)\.(\d+)$/);
  if (dotted) {
    const stem = dotted[1]!;
    const index = dotted[2]!;
    if (index !== "0") bases.push(`${stem}.0`);
  }
  return bases;
}

export function toneFallbackChain(tone: DeliveryTone): DeliveryTone[] {
  switch (tone) {
    case "hot":
      return ["hot", "lift", "calm"];
    case "lift":
      return ["lift", "calm"];
    case "wry":
      return ["wry", "calm"];
    case "calm":
      return ["calm"];
  }
}

/** Priority fragments for the first VO / ElevenLabs batch (Phase 2). */
export const PRIORITY_CLIP_BASES: readonly { clipId: string; tones: readonly DeliveryTone[]; note: string }[] =
  [
    { clipId: "call.homer.0", tones: ["hot", "lift"], note: "Home run primary" },
    { clipId: "call.homer.1", tones: ["hot"], note: "Home run alt" },
    { clipId: "call.k-looking.0", tones: ["hot", "lift"], note: "Punchout looking" },
    { clipId: "call.k-swinging.0", tones: ["hot", "lift"], note: "Punchout swinging" },
    { clipId: "call.walk.0", tones: ["calm", "lift"], note: "Walk" },
    { clipId: "call.single.0", tones: ["calm", "lift"], note: "Single" },
    { clipId: "call.double.0", tones: ["lift", "hot"], note: "Double" },
    { clipId: "call.groundout.0", tones: ["calm", "wry"], note: "Routine / big-spot soft out" },
    { clipId: "call.strike-looking.0", tones: ["calm"], note: "Taken strike" },
    { clipId: "call.ball.0", tones: ["calm"], note: "Ball" },
    { clipId: "call.whiff.0", tones: ["calm"], note: "Whiff" },
    { clipId: "call.foul.0", tones: ["calm"], note: "Foul" },
    { clipId: "call.flyout.0", tones: ["calm"], note: "Fly out" },
    { clipId: "call.popup.0", tones: ["calm"], note: "Pop up" },
    { clipId: "call.lineout.0", tones: ["calm"], note: "Line out" },
    { clipId: "bridge.count.0", tones: ["calm"], note: "Count bridge" },
    { clipId: "station-id.0", tones: ["calm"], note: "Eric station ID" },
    { clipId: "vendor.dogs.0", tones: ["lift"], note: "Eric vendor dogs" },
    { clipId: "vendor.beer.0", tones: ["lift"], note: "Eric vendor beer" },
    { clipId: "vendor.programs.0", tones: ["lift"], note: "Eric vendor programs" },
    { clipId: "gameover.walkoff.0", tones: ["hot"], note: "Walk-off" },
    { clipId: "color.chase.0", tones: ["wry"], note: "Color: chase" },
    { clipId: "color.barrel.0", tones: ["lift"], note: "Color: barrel" },
    { clipId: "color.tension.0", tones: ["lift"], note: "Color: leverage" },
    { clipId: "color.taken-cookie.0", tones: ["wry"], note: "Color: taken strike" },
  ];

export function listPriorityClipKeys(): string[] {
  const keys: string[] = [];
  for (const row of PRIORITY_CLIP_BASES) {
    for (const tone of row.tones) keys.push(`${row.clipId}__${tone}`);
  }
  return keys;
}

/** @internal test helper — classify without a full NarrationContext */
export function toneForPlayResult(
  result: PlayResult,
  options: { runsScored?: number; highLeverage?: boolean; gameOver?: boolean; weakContact?: boolean } = {},
): DeliveryTone {
  const runs = options.runsScored ?? 0;
  const highLev = options.highLeverage ?? false;
  const walkOff = (options.gameOver ?? false) && runs > 0;
  if (result === "home-run" || walkOff) return "hot";
  if (runs > 0 && highLev) return "hot";
  if (runs > 0) return "lift";
  if (result === "single" || result === "double") return highLev ? "lift" : "calm";
  if (
    options.weakContact &&
    highLev &&
    (result === "ground-out" || result === "pop-up" || result === "fly-out" || result === "line-out")
  ) {
    return "wry";
  }
  return "calm";
}
