import type { Phrase } from "../commentary/VoiceBackend.ts";

/**
 * RadioLog — the broadcast, rendered.
 *
 * When announce mode is "screen-reader" or "both", the list is an ARIA live
 * region. When mode is "booth" (Web Speech carries the words), live updates are
 * off so VoiceOver/NVDA do not double-speak over the booth.
 */

const MAX_LINES = 120;

const SPEAKER_LABEL: Record<Phrase["speaker"], string> = {
  announcer: "Play-by-play",
  color: "Color",
  utility: "Field",
  umpire: "Umpire",
};

export class RadioLog {
  private readonly list: HTMLOListElement;
  private live = false;

  constructor(list: HTMLOListElement) {
    this.list = list;
    this.setLive(false);
  }

  /** Toggle polite live announcements of new lines. */
  setLive(enabled: boolean): void {
    this.live = enabled;
    if (enabled) {
      this.list.setAttribute("role", "log");
      this.list.setAttribute("aria-live", "polite");
      this.list.setAttribute("aria-relevant", "additions");
      this.list.setAttribute("aria-atomic", "false");
    } else {
      this.list.setAttribute("role", "list");
      this.list.setAttribute("aria-live", "off");
      this.list.removeAttribute("aria-relevant");
      this.list.removeAttribute("aria-atomic");
    }
  }

  get isLive(): boolean {
    return this.live;
  }

  append(phrase: Phrase): void {
    const item = document.createElement("li");
    item.className = `log-line log-line--${phrase.speaker}`;

    const speaker = document.createElement("span");
    speaker.className = "log-speaker";
    const label = SPEAKER_LABEL[phrase.speaker];
    speaker.textContent = label;
    speaker.setAttribute("aria-label", label);

    const text = document.createElement("span");
    text.className = "log-text";
    text.textContent = phrase.text;

    item.append(speaker, text);
    this.list.append(item);

    while (this.list.childElementCount > MAX_LINES) {
      this.list.firstElementChild?.remove();
    }

    const nearBottom = this.list.scrollHeight - this.list.scrollTop - this.list.clientHeight < 80;
    if (nearBottom) this.list.scrollTop = this.list.scrollHeight;
  }

  clear(): void {
    this.list.replaceChildren();
  }
}
