import type { ContactTier } from "../timing/SwingJudge.ts";
import { CONTACT_WINDOW_MS, PERFECT_WINDOW_MS, SWING_WINDOW_MS } from "../timing/Timeline.ts";

/**
 * SwingReadout — what your last swing was worth, in milliseconds.
 *
 * `aria-live` on the element makes this the blind feedback channel for early/late
 * ms. Thresholds follow the active difficulty windows when provided.
 */

const CALIBRATION_HINT_MS = 110;

const TIER_TEXT: Record<ContactTier, string> = {
  solid: "squared up",
  weak: "weak contact",
  "foul-tip": "got a piece of it",
  miss: "swing and a miss",
};

export class SwingReadout {
  private readonly root: HTMLElement;
  private perfectMs = PERFECT_WINDOW_MS;
  private contactMs = CONTACT_WINDOW_MS;

  constructor(root: HTMLElement) {
    this.root = root;
  }

  setWindows(perfectWindowMs: number, contactWindowMs: number): void {
    this.perfectMs = perfectWindowMs;
    this.contactMs = contactWindowMs;
  }

  showSwing(deltaMs: number, contact: ContactTier): void {
    const magnitude = Math.abs(deltaMs);
    const signed = `${deltaMs >= 0 ? "+" : "-"}${magnitude.toFixed(0)} ms`;
    const tier = TIER_TEXT[contact];

    if (magnitude < this.perfectMs) {
      this.set(`${signed} — PERFECT, ${tier}.`, "perfect");
      return;
    }

    const direction = deltaMs < 0 ? "EARLY" : "LATE";
    const tone = deltaMs < 0 ? "early" : "late";

    if (magnitude <= this.contactMs) {
      this.set(`${signed} ${direction} — ${tier}.`, tone);
      return;
    }

    const hint = magnitude > CALIBRATION_HINT_MS ? " Consistently this far off? Run calibration." : "";
    this.set(`${signed} ${direction} — ${tier}.${hint}`, tone);
  }

  /**
   * A pitch went by untouched. If keys were pressed during it, they were outside
   * the swing window entirely — which is the single most confusing failure mode
   * for an uncalibrated player, so it gets said out loud.
   */
  showTake(ignoredPresses: number): void {
    if (ignoredPresses > 0) {
      this.set(
        `Swing not registered — more than ${SWING_WINDOW_MS} ms off the pitch. Run calibration.`,
        "warn",
      );
      return;
    }
    this.set("Took the pitch.", null);
  }

  /** Pitcher release timing vs beat 4. */
  showRelease(deltaMs: number, autoReleased: boolean): void {
    if (autoReleased) {
      this.set("No release — auto late. Pitch left late.", "warn");
      return;
    }
    const magnitude = Math.abs(deltaMs);
    const signed = `${deltaMs >= 0 ? "+" : "-"}${magnitude.toFixed(0)} ms`;
    if (magnitude < this.perfectMs) {
      this.set(`${signed} — RELEASE PERFECT.`, "perfect");
      return;
    }
    const direction = deltaMs < 0 ? "EARLY" : "LATE";
    const tone = deltaMs < 0 ? "early" : "late";
    if (magnitude <= this.contactMs) {
      this.set(`${signed} ${direction} release — location drifted.`, tone);
      return;
    }
    this.set(`${signed} ${direction} release — wild / hanging.`, tone);
  }

  showMessage(text: string, tone: Tone = null): void {
    this.set(text, tone);
  }

  private set(text: string, tone: Tone): void {
    this.root.textContent = text;
    this.root.className = tone === null ? "swing-readout" : `swing-readout swing-readout--${tone}`;
  }
}

type Tone = "perfect" | "early" | "late" | "warn" | null;
