import {
  CONTACT_WINDOW_MS,
  LOCATION_EXTENT,
  PERFECT_WINDOW_MS,
  clamp,
  type PitchLocation,
  type PitchProfile,
} from "./Timeline.ts";
import type { TimingBucket, TimingWindows } from "./SwingJudge.ts";

/**
 * ReleaseJudge — pitcher timing vs beat 4, and how that bends the called location.
 */

export interface ReleaseJudgment {
  /** Signed error vs release. Negative early, positive late. */
  deltaMs: number;
  timing: TimingBucket;
  /** 0..1 from timing alone. */
  quality: number;
  /** True when the player never pressed and we auto-released late. */
  autoReleased: boolean;
}

export function judgeRelease(
  deltaMs: number,
  windows?: TimingWindows,
  autoReleased = false,
): ReleaseJudgment {
  const perfectMs = windows?.perfectWindowMs ?? PERFECT_WINDOW_MS;
  const contactMs = windows?.contactWindowMs ?? CONTACT_WINDOW_MS;
  const magnitude = Math.abs(deltaMs);

  const timing: TimingBucket =
    magnitude < perfectMs ? "perfect" : magnitude <= contactMs ? (deltaMs < 0 ? "early" : "late") : "miss";

  let quality: number;
  if (magnitude >= contactMs) quality = 0;
  else if (magnitude < perfectMs) quality = 1 - (magnitude / perfectMs) * 0.15;
  else {
    const span = Math.max(contactMs - perfectMs, 1);
    const t = (magnitude - perfectMs) / span;
    quality = 0.85 - t * 0.5;
  }

  if (autoReleased) quality = Math.min(quality, 0.12);

  return { deltaMs, timing, quality, autoReleased };
}

/**
 * Bend the called location based on release quality.
 *
 * Perfect ≈ as called. Contact-band drifts. Miss / auto-release becomes a
 * meatball or a wild miss — never soft-locks the pitch.
 */
export function applyReleaseDrift(
  intended: PitchLocation,
  release: ReleaseJudgment,
  rng: () => number,
): PitchLocation {
  if (release.timing === "perfect") {
    return {
      horizontal: clamp(intended.horizontal + (rng() - 0.5) * 0.08, -LOCATION_EXTENT, LOCATION_EXTENT),
      vertical: clamp(intended.vertical + (rng() - 0.5) * 0.08, -LOCATION_EXTENT, LOCATION_EXTENT),
    };
  }

  if (release.timing === "early" || release.timing === "late") {
    // Soft pull toward the middle — mistimed releases should drift, not become BP.
    const pull = 0.2 + (1 - release.quality) * 0.28;
    return {
      horizontal: clamp(intended.horizontal * (1 - pull) + (rng() - 0.5) * 0.28, -LOCATION_EXTENT, LOCATION_EXTENT),
      vertical: clamp(intended.vertical * (1 - pull) + (rng() - 0.5) * 0.24, -LOCATION_EXTENT, LOCATION_EXTENT),
    };
  }

  // Miss / wild: occasional meatball, usually sprayed off the plate.
  if (rng() < 0.28) {
    return {
      horizontal: clamp((rng() - 0.5) * 0.35, -LOCATION_EXTENT, LOCATION_EXTENT),
      vertical: clamp((rng() - 0.5) * 0.3, -LOCATION_EXTENT, LOCATION_EXTENT),
    };
  }
  const side = rng() < 0.5 ? -1 : 1;
  return {
    horizontal: clamp(side * (1.35 + rng() * 0.7), -LOCATION_EXTENT, LOCATION_EXTENT),
    vertical: clamp(-0.4 + (rng() - 0.5) * 1.6, -LOCATION_EXTENT, LOCATION_EXTENT),
  };
}

/** Slight hang on a mistimed off-speed pitch. */
export function applyReleaseFlightTweak(profile: PitchProfile, release: ReleaseJudgment): PitchProfile {
  if (release.timing === "perfect" || profile.type === "fastball") return profile;
  const hang = release.timing === "miss" ? 0.06 : 0.03;
  return {
    ...profile,
    flightSeconds: profile.flightSeconds + hang,
    velocityMph: Math.max(60, profile.velocityMph - (release.timing === "miss" ? 3 : 1)),
  };
}
