/**
 * Local accessibility / first-run preferences for Bottom of the Ninth.
 */

export type CoachVerbosity = "full" | "short" | "off";
/**
 * How booth lines reach the listener:
 * - booth: Web Speech TTS (default radio experience); play-by-play log is history only
 * - screen-reader: no booth TTS; play-by-play log is a live region for SR
 * - both: TTS + live log (can double-speak with VoiceOver/NVDA)
 */
export type AnnounceMode = "booth" | "screen-reader" | "both";
/**
 * How booth words are produced when announce mode allows audio:
 * - speech: OS Web Speech (default)
 * - sampled: live cast TTS (Adam/Brian/Eric) with sample bank + Web Speech fallback
 */
export type BoothVoice = "speech" | "sampled";

export interface Prefs {
  speechRate: number;
  coachVerbosity: CoachVerbosity;
  announceMode: AnnounceMode;
  boothVoice: BoothVoice;
  radioFilterDefault: boolean;
  calibrationSkipped: boolean;
  broadcastTheme: string;
}

const STORAGE_KEY = "botn.prefs";

const DEFAULTS: Prefs = {
  speechRate: 1,
  coachVerbosity: "full",
  announceMode: "booth",
  boothVoice: "sampled",
  // Off by default so ElevenLabs cast WAVs stay intelligible; AM is opt-in flavor.
  radioFilterDefault: false,
  calibrationSkipped: false,
  broadcastTheme: "default",
};

const CAST_CLARITY_MIGRATION = "botn.castClarity.v1";

export function loadPrefs(): Prefs {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULTS };
    const parsed = JSON.parse(raw) as Partial<Prefs>;
    let radioFilterDefault =
      typeof parsed.radioFilterDefault === "boolean"
        ? parsed.radioFilterDefault
        : DEFAULTS.radioFilterDefault;
    let boothVoice: BoothVoice = isBoothVoice(parsed.boothVoice)
      ? parsed.boothVoice
      : DEFAULTS.boothVoice;

    // One-time: force sampled booth + clear AM so Adam/Brian/Eric are audible.
    if (localStorage.getItem(CAST_CLARITY_MIGRATION) !== "1") {
      boothVoice = "sampled";
      radioFilterDefault = false;
      localStorage.setItem(CAST_CLARITY_MIGRATION, "1");
      const migrated: Prefs = {
        speechRate: clampRate(parsed.speechRate ?? DEFAULTS.speechRate),
        coachVerbosity: isCoachVerbosity(parsed.coachVerbosity)
          ? parsed.coachVerbosity
          : DEFAULTS.coachVerbosity,
        announceMode: isAnnounceMode(parsed.announceMode) ? parsed.announceMode : DEFAULTS.announceMode,
        boothVoice,
        radioFilterDefault,
        calibrationSkipped: parsed.calibrationSkipped === true,
        broadcastTheme:
          typeof parsed.broadcastTheme === "string" && parsed.broadcastTheme
            ? parsed.broadcastTheme
            : DEFAULTS.broadcastTheme,
      };
      savePrefs(migrated);
      return migrated;
    }

    return {
      speechRate: clampRate(parsed.speechRate ?? DEFAULTS.speechRate),
      coachVerbosity: isCoachVerbosity(parsed.coachVerbosity)
        ? parsed.coachVerbosity
        : DEFAULTS.coachVerbosity,
      announceMode: isAnnounceMode(parsed.announceMode) ? parsed.announceMode : DEFAULTS.announceMode,
      boothVoice,
      radioFilterDefault,
      calibrationSkipped: parsed.calibrationSkipped === true,
      broadcastTheme:
        typeof parsed.broadcastTheme === "string" && parsed.broadcastTheme
          ? parsed.broadcastTheme
          : DEFAULTS.broadcastTheme,
    };
  } catch {
    return { ...DEFAULTS };
  }
}

export function savePrefs(prefs: Prefs): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
  } catch {
    /* ignore */
  }
}

export function patchPrefs(patch: Partial<Prefs>): Prefs {
  const next = { ...loadPrefs(), ...patch };
  if (patch.speechRate !== undefined) next.speechRate = clampRate(patch.speechRate);
  savePrefs(next);
  return next;
}

function isCoachVerbosity(value: unknown): value is CoachVerbosity {
  return value === "full" || value === "short" || value === "off";
}

export function isAnnounceMode(value: unknown): value is AnnounceMode {
  return value === "booth" || value === "screen-reader" || value === "both";
}

export function isBoothVoice(value: unknown): value is BoothVoice {
  return value === "speech" || value === "sampled";
}

function clampRate(value: number): number {
  if (!Number.isFinite(value)) return 1;
  return Math.min(1.4, Math.max(0.7, value));
}

/** CSS variable tokens for contract slot `broadcast-theme`. */
export const BROADCAST_THEMES: Record<
  string,
  { background: string; panel: string; accent: string; score: string; warning: string }
> = {
  default: {
    background: "#0b1220",
    panel: "#162238",
    accent: "#c41230",
    score: "#f2f5fa",
    warning: "#f0c14b",
  },
  "night-signal": {
    background: "#070b14",
    panel: "#121c30",
    accent: "#41b6e6",
    score: "#e8f4ff",
    warning: "#7dd3fc",
  },
  "day-call": {
    background: "#1a2438",
    panel: "#243552",
    accent: "#e8a317",
    score: "#fff8e7",
    warning: "#ffd56a",
  },
};

export function applyBroadcastTheme(themeId: string): void {
  const fallback = BROADCAST_THEMES.default!;
  const theme = BROADCAST_THEMES[themeId] ?? fallback;
  const root = document.documentElement;
  root.style.setProperty("--bg", theme.background);
  root.style.setProperty("--bg-2", theme.background);
  root.style.setProperty("--panel", theme.panel);
  root.style.setProperty("--accent", theme.accent);
  root.style.setProperty("--ink", theme.score);
  root.style.setProperty("--warn", theme.warning);
  root.dataset.broadcastTheme = themeId in BROADCAST_THEMES ? themeId : "default";
}

/** Read equipped theme from arcade localStorage when embedded. */
export function readArcadeBroadcastTheme(): string | null {
  try {
    // Arcade `src/core/storage.js` namespaces each key as `cadegames:v1:<name>`.
    const raw = localStorage.getItem("cadegames:v1:cosmetics");
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { broadcastTheme?: string };
    const value = parsed?.broadcastTheme;
    return typeof value === "string" && value && value !== "default" ? value : null;
  } catch {
    return null;
  }
}
