import type { AudioEngine } from "../audio/AudioEngine.ts";
import type { DifficultyConfig } from "../game/Difficulty.ts";
import { PITCH_PULSE_SEC, type PitchTimeline } from "../timing/Timeline.ts";
import { WINDUP_BEATS } from "../audio/voices/windup.ts";

/**
 * TimingCoach — sighted mirror of the five-beat delivery.
 *
 * Decorative only (`aria-hidden`). Blind players learn from the field-bus beat
 * tones / plate tick / spoken "swing"; this strip must never be required to time
 * a pitch, and it must not spam a screen reader every beat.
 */

const BEAT_COUNT = WINDUP_BEATS + 2; // 1–3 windup, 4 release, 5 plate

export type CoachRole = "bat" | "pitch";

export class TimingCoach {
  private readonly root: HTMLElement;
  private readonly engine: AudioEngine;
  private getDifficulty: () => DifficultyConfig;
  private cells: HTMLElement[] = [];
  private swingLabel: HTMLElement | null = null;
  private releaseLabel: HTMLElement | null = null;
  private hint: HTMLElement | null = null;
  private raf: number | null = null;
  private active: PitchTimeline | null = null;
  private role: CoachRole = "bat";

  constructor(root: HTMLElement, engine: AudioEngine, getDifficulty: () => DifficultyConfig) {
    this.root = root;
    this.engine = engine;
    this.getDifficulty = getDifficulty;
    this.mount();
  }

  private mount(): void {
    this.root.setAttribute("aria-hidden", "true");
    this.root.className = "timing-coach";

    const strip = document.createElement("div");
    strip.className = "timing-coach-strip";

    this.cells = [];
    for (let i = 1; i <= BEAT_COUNT; i++) {
      const cell = document.createElement("div");
      cell.className = "timing-coach-beat";
      cell.dataset.beat = String(i);
      const num = document.createElement("span");
      num.className = "timing-coach-num";
      num.textContent = String(i);
      cell.append(num);
      if (i === 4) {
        this.releaseLabel = document.createElement("span");
        this.releaseLabel.className = "timing-coach-tag";
        this.releaseLabel.textContent = "release";
        cell.append(this.releaseLabel);
      }
      if (i === 5) {
        this.swingLabel = document.createElement("span");
        this.swingLabel.className = "timing-coach-tag timing-coach-tag--swing";
        this.swingLabel.textContent = "swing";
        cell.append(this.swingLabel);
      }
      strip.append(cell);
      this.cells.push(cell);
    }

    this.hint = document.createElement("p");
    this.hint.className = "timing-coach-hint";
    this.hint.textContent = "Count 1–2–3–4, swing on 5. Fastballs land on the beat.";

    this.root.replaceChildren(strip, this.hint);
    this.applyVisibility();
  }

  setDifficulty(getDifficulty: () => DifficultyConfig): void {
    this.getDifficulty = getDifficulty;
    this.applyVisibility();
  }

  setRole(role: CoachRole): void {
    this.role = role;
    if (this.hint) {
      this.hint.textContent =
        role === "pitch"
          ? "Count 1–2–3, release on 4. Then the ball flies to the plate."
          : "Count 1–2–3–4, swing on 5. Fastballs land on the beat.";
    }
    if (this.releaseLabel) {
      this.releaseLabel.classList.toggle("timing-coach-tag--swing", role === "pitch");
    }
    if (this.swingLabel) {
      this.swingLabel.classList.toggle("timing-coach-tag--swing", role === "bat");
    }
  }

  /** Start tracking a scheduled pitch (heard-time sync via ClockBridge). */
  arm(timeline: PitchTimeline): void {
    this.active = timeline;
    this.clearActive();
    this.applyVisibility();
    if (!this.getDifficulty().visualCoach) return;
    this.stopRaf();
    const tick = (): void => {
      if (!this.active) return;
      this.renderBeat();
      this.raf = requestAnimationFrame(tick);
    };
    this.raf = requestAnimationFrame(tick);
  }

  /** Clear highlights after the pitch resolves or is cancelled. */
  clear(): void {
    this.active = null;
    this.stopRaf();
    this.clearActive();
    if (this.swingLabel) this.swingLabel.classList.remove("timing-coach-tag--flash");
    if (this.releaseLabel) this.releaseLabel.classList.remove("timing-coach-tag--flash");
  }

  private applyVisibility(): void {
    const on = this.getDifficulty().visualCoach;
    this.root.hidden = !on;
  }

  private renderBeat(): void {
    const timeline = this.active;
    if (!timeline) return;

    this.engine.clock.sample();
    const nowPerf = performance.now();
    // Convert each beat's audio time to perceived performance time.
    const beatTimes = Array.from({ length: BEAT_COUNT }, (_, i) => {
      const audioT =
        i < WINDUP_BEATS
          ? timeline.startTime + i * PITCH_PULSE_SEC
          : i === WINDUP_BEATS
            ? timeline.releaseTime
            : timeline.plateTime;
      return this.engine.clock.audioToPerf(audioT);
    });

    let current = 0;
    for (let i = 0; i < beatTimes.length; i++) {
      if (nowPerf >= (beatTimes[i] as number) - 20) current = i + 1;
    }

    this.cells.forEach((cell, index) => {
      const beat = index + 1;
      cell.classList.toggle("timing-coach-beat--on", beat === current);
      cell.classList.toggle("timing-coach-beat--done", beat < current);
    });

    if (this.getDifficulty().visualSwingFlash) {
      if (this.role === "bat" && this.swingLabel && nowPerf >= timeline.perceivedPlateMs - 30) {
        this.swingLabel.classList.add("timing-coach-tag--flash");
      }
      if (this.role === "pitch" && this.releaseLabel) {
        const releasePerf = this.engine.clock.audioToPerf(timeline.releaseTime);
        if (nowPerf >= releasePerf - 30) {
          this.releaseLabel.classList.add("timing-coach-tag--flash");
        }
      }
    }

    if (nowPerf > timeline.perceivedPlateMs + 400) {
      this.clear();
    }
  }

  private clearActive(): void {
    for (const cell of this.cells) {
      cell.classList.remove("timing-coach-beat--on", "timing-coach-beat--done");
    }
  }

  private stopRaf(): void {
    if (this.raf === null) return;
    cancelAnimationFrame(this.raf);
    this.raf = null;
  }
}
