/**
 * Best-of-N series wrapper around single-game sessions.
 *
 * SessionMode / campaign coordination (Season & Playoff agents):
 * - Gate `SessionMode` includes `"series"` | `"playoff"` (season uses `campaignKind`).
 * - `GameSave.campaign` is a discriminated union: `{ kind: "series" | "season" | "playoff", ... }`.
 * - Durable series shell also lives in `botn.series.v1` so meta survives even when
 *   the mid-game save is cleared between contests.
 */

import type { DifficultyId } from "./Difficulty.ts";
import { isDifficultyId } from "./Difficulty.ts";
import type { PlayerSide } from "./PlayerSide.ts";
import { isPlayerSide } from "./PlayerSide.ts";
import type { RoleLock, SessionLength } from "./SessionOptions.ts";
import { isRoleLock, isSessionLength } from "./SessionOptions.ts";
import { AWAY_TEAM, HOME_TEAM } from "./Teams.ts";

export const SERIES_STORAGE_KEY = "botn.series.v1";

export type SeriesBestOf = 3 | 5;

export function isSeriesBestOf(value: unknown): value is SeriesBestOf {
  return value === 3 || value === 5;
}

/** Wins needed to clinch a best-of-N (first to ceil(N/2)). */
export function winsNeeded(bestOf: SeriesBestOf): number {
  return Math.ceil(bestOf / 2);
}

/**
 * Persisted / campaign payload for a Best-of-3 series.
 * `kind` discriminates GameSave.campaign from season/playoff shells.
 */
export interface SeriesCampaignV1 {
  readonly kind: "series";
  readonly v: 1;
  readonly bestOf: SeriesBestOf;
  readonly winsHome: number;
  readonly winsAway: number;
  readonly gamesPlayed: number;
  readonly playerSide: PlayerSide;
  readonly length: SessionLength;
  readonly roleLock: RoleLock;
  readonly difficultyId: DifficultyId;
}

export interface SeriesCreateArgs {
  playerSide: PlayerSide;
  length: SessionLength;
  roleLock: RoleLock;
  difficultyId: DifficultyId;
  bestOf?: SeriesBestOf;
}

export type SeriesGameResult = "home" | "away" | "tie";

export class SeriesState {
  readonly bestOf: SeriesBestOf;
  winsHome: number;
  winsAway: number;
  gamesPlayed: number;
  readonly playerSide: PlayerSide;
  readonly length: SessionLength;
  readonly roleLock: RoleLock;
  readonly difficultyId: DifficultyId;

  constructor(args: SeriesCampaignV1) {
    this.bestOf = args.bestOf;
    this.winsHome = args.winsHome;
    this.winsAway = args.winsAway;
    this.gamesPlayed = args.gamesPlayed;
    this.playerSide = args.playerSide;
    this.length = args.length;
    this.roleLock = args.roleLock;
    this.difficultyId = args.difficultyId;
  }

  static create(args: SeriesCreateArgs): SeriesState {
    return new SeriesState({
      kind: "series",
      v: 1,
      bestOf: args.bestOf ?? 3,
      winsHome: 0,
      winsAway: 0,
      gamesPlayed: 0,
      playerSide: args.playerSide,
      length: args.length,
      roleLock: args.roleLock,
      difficultyId: args.difficultyId,
    });
  }

  /** Current series game number (1-based), capped at bestOf. */
  currentGameNumber(): number {
    if (this.isComplete()) return this.gamesPlayed;
    return Math.min(this.gamesPlayed + 1, this.bestOf);
  }

  winsNeeded(): number {
    return winsNeeded(this.bestOf);
  }

  isComplete(): boolean {
    const need = this.winsNeeded();
    return this.winsHome >= need || this.winsAway >= need;
  }

  /** Home / away side that clinched, or null if series still open. */
  winnerSide(): "home" | "away" | null {
    const need = this.winsNeeded();
    if (this.winsHome >= need) return "home";
    if (this.winsAway >= need) return "away";
    return null;
  }

  playerWonSeries(): boolean {
    return this.winnerSide() === this.playerSide;
  }

  winsFor(side: PlayerSide): number {
    return side === "home" ? this.winsHome : this.winsAway;
  }

  /**
   * Record a finished contest. Ties bump gamesPlayed but award no win.
   * Returns whether the series is now complete.
   */
  recordGame(result: SeriesGameResult): boolean {
    if (this.isComplete()) return true;
    this.gamesPlayed += 1;
    if (result === "home") this.winsHome += 1;
    else if (result === "away") this.winsAway += 1;
    return this.isComplete();
  }

  toCampaign(): SeriesCampaignV1 {
    return {
      kind: "series",
      v: 1,
      bestOf: this.bestOf,
      winsHome: this.winsHome,
      winsAway: this.winsAway,
      gamesPlayed: this.gamesPlayed,
      playerSide: this.playerSide,
      length: this.length,
      roleLock: this.roleLock,
      difficultyId: this.difficultyId,
    };
  }

  /** "Series: Pirates 1, Phillies 0 — Game 2 of 3" */
  scoreLine(): string {
    const need = this.winsNeeded();
    if (this.isComplete()) {
      const winner = this.winnerSide() === "home" ? HOME_TEAM.shortName : AWAY_TEAM.shortName;
      return `Series final: ${HOME_TEAM.shortName} ${this.winsHome}–${this.winsAway} ${AWAY_TEAM.shortName}. ${winner} take the series.`;
    }
    return `Series: ${HOME_TEAM.shortName} ${this.winsHome}, ${AWAY_TEAM.shortName} ${this.winsAway}. Game ${this.currentGameNumber()} of ${this.bestOf} (first to ${need}).`;
  }

  /** Player-facing clinch line for the end card. */
  resultLine(): string {
    const you = this.winsFor(this.playerSide);
    const them = this.winsFor(this.playerSide === "home" ? "away" : "home");
    if (this.playerWonSeries()) return `You take the series ${you}–${them}`;
    if (this.isComplete()) return `They take the series ${them}–${you}`;
    return this.scoreLine();
  }

  /** Spoken booth break before the next game. */
  boothBreakLine(): string {
    const next = this.currentGameNumber();
    const ordinal =
      next === 2
        ? "game two"
        : next === 3
          ? "game three"
          : next === 4
            ? "game four"
            : next === 5
              ? "game five"
              : `game ${next}`;
    return `We'll be right back for ${ordinal} of the series. ${this.scoreLine()}`;
  }

  /** Opening announce when a series begins. */
  seriesOpenLine(): string {
    return `Best of ${this.bestOf} series. First to ${this.winsNeeded()} wins. ${this.scoreLine()}`;
  }
}

export function isSeriesCampaign(raw: unknown): raw is SeriesCampaignV1 {
  if (!raw || typeof raw !== "object") return false;
  const s = raw as Partial<SeriesCampaignV1>;
  if (s.kind !== "series" || s.v !== 1) return false;
  if (!isSeriesBestOf(s.bestOf)) return false;
  if (typeof s.winsHome !== "number" || typeof s.winsAway !== "number") return false;
  if (typeof s.gamesPlayed !== "number") return false;
  if (s.winsHome < 0 || s.winsAway < 0 || s.gamesPlayed < 0) return false;
  const cap = s.bestOf;
  if (s.winsHome > cap || s.winsAway > cap || s.gamesPlayed > cap) return false;
  if (!isPlayerSide(String(s.playerSide ?? ""))) return false;
  if (!isSessionLength(s.length)) return false;
  if (!isRoleLock(s.roleLock)) return false;
  if (!isDifficultyId(String(s.difficultyId ?? ""))) return false;
  return true;
}

export function seriesFromCampaign(raw: unknown): SeriesState | null {
  return isSeriesCampaign(raw) ? new SeriesState(raw) : null;
}

export function loadSeries(): SeriesState | null {
  try {
    const raw = localStorage.getItem(SERIES_STORAGE_KEY);
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    return seriesFromCampaign(parsed);
  } catch {
    return null;
  }
}

export function writeSeries(series: SeriesState): void {
  try {
    localStorage.setItem(SERIES_STORAGE_KEY, JSON.stringify(series.toCampaign()));
  } catch {
    /* private browsing / quota */
  }
}

export function clearSeries(): void {
  try {
    localStorage.removeItem(SERIES_STORAGE_KEY);
  } catch {
    /* ignore */
  }
}

/** Map a finished game score to a series result. */
export function seriesResultFromScore(score: { home: number; away: number }): SeriesGameResult {
  if (score.home > score.away) return "home";
  if (score.away > score.home) return "away";
  return "tie";
}
