/**
 * Minimum dead air after a pitch before the next windup — on top of waiting for
 * the booth to finish. Radio baseball needs room for the count, the chess, and
 * a breath; 1.5 s was a video-game cadence.
 */
const BETWEEN_PITCHES_SEC = 5.2;
/** Extra hold after a half-inning break call before play resumes. */
const INNING_BREAK_SEC = 2.8;
/** Padding after the commentary queue goes idle so the last syllable clears. */
const BOOTH_CLEAR_PAD_MS = 400;

