function refreshResumeGate(): void {
  const save = loadGameSave();
  if (!save) {
    resumeGameButton.hidden = true;
    resumeHint.hidden = true;
    resumeHint.textContent = "";
    playBallButton.textContent = "Play Ball";
    return;
  }
  resumeGameButton.hidden = false;
  resumeHint.hidden = false;
  const summary = describeGameSave(save);
  const playoffNote = isPlayoffCampaign(save.campaign)
    ? ` ${new PlayoffState(save.campaign).scoreLine()}`
    : "";
  const seriesNote =
    !playoffNote && isSeriesCampaign(save.campaign)
      ? ` ${new SeriesState(save.campaign).scoreLine()}`
      : "";
  const season = resolveSeasonFromStorage(save.campaign);
  const seasonNote =
    !playoffNote && !seriesNote && season && !isSeasonComplete(season)
      ? ` ${describeSeasonStandings(season)}`
      : "";
  const challengeNote =
    !playoffNote && !seriesNote && !seasonNote && isChallengeCampaign(save.campaign)
      ? ` Challenge: ${getChallenge(save.campaign.id).title}.`
      : "";
  resumeGameButton.textContent = "Resume broadcast";
  resumeHint.textContent =
    `Saved game: ${summary}.${playoffNote}${seriesNote}${seasonNote}${challengeNote} Resume continues that broadcast; Play Ball starts fresh and clears series/playoff/season/challenge progress.`;
  playBallButton.textContent = "New game";
}

function syncSeasonScheduleOptions(unit: "game" | "series", selected: number): void {
  const options = Array.from(seasonScheduleSelect.options);
  for (const opt of options) {
    // 6 is always available; 3 only for series; 12 only for games.
    if (opt.value === "3") opt.hidden = unit !== "series";
    else if (opt.value === "12") opt.hidden = unit !== "game";
    else opt.hidden = false;
  }
  // Refresh labels for the shared "6" option.
  const six = options.find((o) => o.value === "6");
  if (six) six.textContent = unit === "series" ? "6 series" : "6 games";
  const three = options.find((o) => o.value === "3");
  if (three) three.textContent = "3 series";
  const twelve = options.find((o) => o.value === "12");
  if (twelve) twelve.textContent = "12 games";
  const allowed =
    unit === "series"
      ? selected === 3 || selected === 6
        ? selected
        : 6
      : selected === 6 || selected === 12
        ? selected
        : 6;
  seasonScheduleSelect.value = String(allowed);
}

function syncSessionGate(): void {
  let mode = isSessionMode(sessionModeSelect.value) ? sessionModeSelect.value : "exhibition";
  const length = Number(sessionLengthSelect.value);
  const roleLock = isRoleLock(roleLockSelect.value) ? roleLockSelect.value : "both";
  let campaignKind = isCampaignKind(campaignKindSelect.value) ? campaignKindSelect.value : "none";
  let seasonUnit = isSeasonUnit(seasonUnitSelect.value) ? seasonUnitSelect.value : "game";
  const playoffFormat = isPlayoffFormat(playoffFormatSelect.value)
    ? playoffFormatSelect.value
    : "bracket";
  syncSeasonScheduleOptions(seasonUnit, Number(seasonScheduleSelect.value));
  const seasonScheduleNum = Number(seasonScheduleSelect.value);
  const seasonSchedule = isSeasonScheduleOption(seasonScheduleNum) ? seasonScheduleNum : 6;
  let challengeGate = challengePickSelect.value;

  // Series / playoff / season clear the challenge picker.
  if (mode === "series" || mode === "playoff" || campaignKind === "season") {
    challengeGate = "none";
    challengePickSelect.value = "none";
  }

  const challengeId = resolveChallengeGateValue(challengeGate);

  // Practice / series / playoff own the slate — no season wrapper beside them.
  if (mode === "practice" || mode === "series" || mode === "playoff") campaignKind = "none";
  // Picking Season forces exhibition games (not Bo3 / playoff mode).
  if (campaignKind === "season" && (mode === "series" || mode === "playoff")) {
    mode = "exhibition";
    sessionModeSelect.value = "exhibition";
  }
  sessionOptions = normalizeSessionOptions({
    mode,
    length: isSessionLength(length) ? length : 9,
    roleLock,
    campaignKind,
    seasonSchedule,
    seasonUnit,
    playoffFormat,
    challengeId,
  });
  campaignKindSelect.value = sessionOptions.campaignKind;
  seasonUnitSelect.value = sessionOptions.seasonUnit;
  seasonScheduleSelect.value = String(sessionOptions.seasonSchedule);
  playoffFormatSelect.value = sessionOptions.playoffFormat;
  sessionModeSelect.value = sessionOptions.mode;
  sessionLengthSelect.value = String(sessionOptions.length);
  roleLockSelect.value = sessionOptions.roleLock;
  const challengeOn = sessionOptions.challengeId !== "none";
  const practice = sessionOptions.mode === "practice";
  const seriesOrPlayoff =
    sessionOptions.mode === "series" || sessionOptions.mode === "playoff";
  const seasonOn = sessionOptions.campaignKind === "season";
  const playoffOn = sessionOptions.mode === "playoff";
  sessionLengthLabel.hidden = practice || challengeOn;
  roleLockLabel.hidden = practice || challengeOn;
  campaignKindLabel.hidden = practice || seriesOrPlayoff || challengeOn;
  seasonUnitLabel.hidden = !seasonOn || challengeOn;
  seasonScheduleLabel.hidden = !seasonOn || challengeOn;
  playoffFormatLabel.hidden = !playoffOn || challengeOn;
  challengePickLabel.hidden = seriesOrPlayoff || seasonOn;
  saveSessionOptions(sessionOptions);
}

