resumeGameButton.addEventListener("click", () => {
  const save = loadGameSave();
  if (!save) {
    refreshResumeGate();
    return;
  }
  pendingResume = save;
  // Restore gate selects to match the save so session length / side stay consistent.
  playerSideSelect.value = save.playerSide;
  sessionModeSelect.value = save.session.mode;
  campaignKindSelect.value = save.session.campaignKind ?? "none";
  seasonUnitSelect.value = save.session.seasonUnit ?? "game";
  seasonScheduleSelect.value = String(save.session.seasonSchedule ?? 6);
  playoffFormatSelect.value = save.session.playoffFormat ?? "bracket";
  sessionLengthSelect.value = String(save.session.length);
  roleLockSelect.value = save.session.roleLock;
  challengePickSelect.value =
    save.session.challengeId && save.session.challengeId !== "none"
      ? save.session.challengeId
      : "none";
  syncSessionGate();
  playBallButton.disabled = true;
  resumeGameButton.disabled = true;
  void start().catch((error: unknown) => {
    playBallButton.disabled = false;
    resumeGameButton.disabled = false;
    pendingResume = null;
    refreshResumeGate();
    // eslint-disable-next-line no-console
    console.error("Failed to resume the broadcast", error);
  });
});

async function start(): Promise<void> {
  const resumeSave = pendingResume;
  pendingResume = null;

  // AudioContext construction and resume both live behind the user gesture.
  const engine = new AudioEngine();
  await engine.resume();
  // SpeechSynthesis also needs the gesture, or the first call is silently dropped.
  warmUpSpeech();
  // Decode bat/glove/crowd clips before the bed starts so we don't flash static.
  await engine.samples.load(engine.ctx);

  const sideValue = resumeSave?.playerSide ?? playerSideSelect.value;
  const playerSide: PlayerSide = isPlayerSide(sideValue) ? sideValue : "home";
  savePlayerSide(playerSide);
  const playerTeam = teamForSide(playerSide);

  if (resumeSave) {
    sessionOptions = normalizeSessionOptions(resumeSave.session);
    saveSessionOptions(sessionOptions);
    if (isDifficultyId(resumeSave.difficultyId)) {
      saveDifficultyId(resumeSave.difficultyId);
    }
  }

  /**
   * Active Best-of-3 shell (null for exhibition / practice / season / playoff).
   * Restored from GameSave.campaign on Resume; created fresh on Play Ball.
   * Season uses campaignKind + SeasonPersist; playoff uses PlayoffState below.
   */
  let activeSeries: SeriesState | null = null;
  /** Thin playoff bracket; owns its nested SeriesState (do not also set activeSeries). */
  let activePlayoff: PlayoffState | null = null;
  if (resumeSave) {
    if (sessionOptions.campaignKind !== "season") {
      activePlayoff =
        playoffFromCampaign(resumeSave.campaign) ??
        (resumeSave.session.mode === "playoff" ? loadPlayoff() : null);
      if (activePlayoff) {
        writePlayoff(activePlayoff);
        clearSeries();
      } else {
        activeSeries =
          seriesFromCampaign(resumeSave.campaign) ??
          (resumeSave.session.mode === "series" ? loadSeries() : null);
        if (activeSeries) writeSeries(activeSeries);
      }
    }
  } else if (sessionOptions.mode === "playoff" && sessionOptions.campaignKind !== "season") {
    activePlayoff = PlayoffState.create({
      playerSide,
      length: sessionOptions.length,
      roleLock: sessionOptions.roleLock,
      difficultyId: loadDifficultyId(),
      format: sessionOptions.playoffFormat,
    });
    writePlayoff(activePlayoff);
    clearSeries();
    clearSeason();
  } else if (sessionOptions.mode === "series" && sessionOptions.campaignKind !== "season") {
    activeSeries = SeriesState.create({
      playerSide,
      length: sessionOptions.length,
      roleLock: sessionOptions.roleLock,
      difficultyId: loadDifficultyId(),
    });
    writeSeries(activeSeries);
    clearPlayoff();
    clearSeason();
  } else {
    clearSeries();
    clearPlayoff();
  }

  gate.hidden = true;
  booth.hidden = false;
  // Collapse only the optional visual board on small screens — feed/score stay up.
  if (window.matchMedia("(max-width: 900px)").matches) {
    requireElement<HTMLDetailsElement>("gameday-fold").open = false;
  }

  const activeChallenge: ChallengePreset | null =
    sessionOptions.challengeId !== "none" ? getChallenge(sessionOptions.challengeId) : null;
  let challengeSeed = activeChallenge?.seed ?? 0;
  if (resumeSave && isChallengeCampaign(resumeSave.campaign)) {
    challengeSeed = resumeSave.campaign.seed;
  }
  const rng = activeChallenge ? createSeededRng(challengeSeed) : Math.random;
  let practicePitchesThrown =
    resumeSave && isChallengeCampaign(resumeSave.campaign)
      ? (resumeSave.campaign.practicePitchesThrown ?? 0)
      : 0;
  let practiceScore =
    resumeSave && isChallengeCampaign(resumeSave.campaign)
      ? (resumeSave.campaign.practiceScore ?? 0)
      : 0;
  /** Last resolved challenge outcome (for end card / event detail). */
  let lastChallengeOutcome: ChallengeOutcome | null = null;

  const radioLog = new RadioLog(requireElement<HTMLOListElement>("radio-log"));
  const liveScore = new LiveScore(requireElement("live-score"));
  const gameday = new GamedayBoard(requireElement("gameday"));
  gameday.setPlayerTeam(playerTeam.shortName);
  const liveStats = new LiveStats(HOME_TEAM, AWAY_TEAM);
  const input = new SwingInput();
  const calibration = new Calibration(engine, input, {
    onStatus: (text) => {
      requireElement("calibration-status").textContent = text;
    },
  });
  const readout = new SwingReadout(requireElement("swing-readout"));
  const difficultyAnnounce = requireElement("difficulty-announce");
  const spaceHint = requireElement("space-hint");
  const pitchCall = new PitchCallPanel(requireElement("pitch-call"));

  function applyAnnounceMode(): void {
    // Booth TTS carries lines by default; live log would double-speak with SR.
    radioLog.setLive(prefs.announceMode === "screen-reader" || prefs.announceMode === "both");
  }
  applyAnnounceMode();

  /** Coach tips: always update the status region; TTS only when booth modes allow. */
  function coachSpeak(
    text: string,
    options: { energy?: number; speaker?: "announcer" | "color" | "umpire"; interrupt?: boolean } = {},
  ): void {
    difficultyAnnounce.textContent = text;
    if (prefs.coachVerbosity === "off") return;
    if (prefs.announceMode === "screen-reader") return;
    // Don't let OS coach TTS steal the booth identity when directed samples are on.
    if (prefs.boothVoice === "sampled") return;
    const request: Parameters<typeof speakNow>[0] = {
      text,
      speaker: options.speaker ?? "announcer",
      energy: options.energy ?? 0.35,
    };
    if (options.interrupt !== undefined) request.interrupt = options.interrupt;
    speakNow(request);
  }

  // Booth words: live cast TTS (Adam/Brian/Eric) speaking real phrase text + names.
  // Sample bank / OS speech are fallbacks when the TTS API is unavailable.
  // Delivery calls stay silent so they do not talk over the windup pulse.
  const speechBackend = new SpeechVoiceBackend(engine, radioLog, () => prefs.announceMode);
  const sampledBackend = new SampledVoiceBackend({
    engine,
    log: radioLog,
    fallback: speechBackend,
    getAnnounceMode: () => prefs.announceMode,
    baseUrl: new URL("sounds/booth/", window.location.href),
  });
  await sampledBackend.load();
  if (sampledBackend.loadedClipCount === 0) {
    // eslint-disable-next-line no-console
    console.warn("Booth sample bank failed to load; speech-only fallback if cast TTS is down.");
  } else {
    // eslint-disable-next-line no-console
    console.info(`Booth sample bank loaded: ${sampledBackend.loadedClipCount} clips (cast TTS fallback)`);
  }

  const castBackend = new CastVoiceBackend({
    engine,
    log: radioLog,
    samples: sampledBackend,
    speech: speechBackend,
    getAnnounceMode: () => prefs.announceMode,
  });
  await castBackend.warmUp();

  const backend: VoiceBackend = {
    estimateDuration: (phrase) => activeBoothBackend().estimateDuration(phrase),
    speak: (phrase, at) => activeBoothBackend().speak(phrase, at),
  };

  function activeBoothBackend(): VoiceBackend {
    return prefs.boothVoice === "sampled" ? castBackend : speechBackend;
  }

  const queue = new CommentaryQueue(backend, () => engine.currentTime);
  const crowd = new CrowdBed(engine);
  /** Vendor shouts fire between pitches when the booth is quiet — atmosphere, not dialogue. */
  let pitchesSinceVendor = 0;
  const state = new GameState(HOME_TEAM, AWAY_TEAM, rng, { regulationInnings: sessionOptions.length });
  const selector = new PitchSelector(rng);

  let difficulty: DifficultyConfig = getDifficulty(
    resumeSave && isDifficultyId(resumeSave.difficultyId)
      ? resumeSave.difficultyId
      : loadDifficultyId(),
  );
  selector.setDifficulty(difficulty);
  readout.setWindows(difficulty.perfectWindowMs, difficulty.contactWindowMs);

  // --- Season shell (localized; series/playoff can sit beside this) ----------
  let season: SeasonPersist | null = null;

  function beginSeasonShell(): void {
    if (
      activeChallenge ||
      sessionOptions.mode === "practice" ||
      sessionOptions.mode === "series" ||
      sessionOptions.mode === "playoff" ||
      sessionOptions.campaignKind !== "season"
    ) {
      season = null;
      if (!resumeSave) clearSeason();
      return;
    }
    clearSeries();
    clearPlayoff();
    activeSeries = null;
    activePlayoff = null;
    if (resumeSave) {
      season = resolveSeasonFromStorage(resumeSave.campaign);
      if (season) {
        if (season.unit === "series") season = ensureSeasonSeries(season);
        writeSeason(season);
        sessionOptions = normalizeSessionOptions({
          ...sessionOptions,
          mode: "exhibition",
          campaignKind: "season",
          seasonSchedule: season.scheduleLength,
          seasonUnit: season.unit ?? "game",
          length: season.length,
          roleLock: season.roleLock,
        });
        saveSessionOptions(sessionOptions);
        // Season-of-series owns the nested Bo3 — mirror into activeSeries for UI.
        if (season.unit === "series") {
          activeSeries = seasonSeriesState(season);
        }
      }
      return;
    }
    season = createSeason({
      scheduleLength: sessionOptions.seasonSchedule,
      playerSide,
      length: sessionOptions.length,
      roleLock: sessionOptions.roleLock,
      difficultyId: difficulty.id,
      unit: sessionOptions.seasonUnit,
    });
    writeSeason(season);
    if (season.unit === "series") {
      activeSeries = seasonSeriesState(season);
    }
  }

  beginSeasonShell();

  function campaignBlob(): unknown {
    if (activeChallenge) {
      return toChallengeCampaign(
        activeChallenge.id,
        challengeSeed,
        activeChallenge.kind === "practice"
          ? { pitchesThrown: practicePitchesThrown, score: practiceScore }
          : undefined,
      );
    }
    if (season) {
      // Keep nested series in sync before persisting.
      if (season.unit === "series" && activeSeries && !activeSeries.isComplete()) {
        season = { ...season, currentSeries: activeSeries.toCampaign() };
      }
      return toSeasonCampaign(season);
    }
    if (activePlayoff) return activePlayoff.toCampaign();
    if (activeSeries) return activeSeries.toCampaign();
    return undefined;
  }

  function announceSeasonLine(): string | null {
    if (!season) return null;
    return describeSeasonCampaignLine(season);
  }
  /** BR-8 thin bullpen — fatigue + one closer call per game. */
  let bullpen: BullpenPersist = createBullpenState();
  if (resumeSave) {
    try {
      state.restore(resumeSave.game);
      liveStats.restore(resumeSave.live);
      bullpen = restoreBullpen(resumeSave.bullpen);
      // Reconcile closer-in flags from restored active arms (older saves).
      if (state.pitcherForSide("home").name === HOME_TEAM.closer.name) {
        bullpen = { ...bullpen, homeCloserIn: true };
      }
      if (state.pitcherForSide("away").name === AWAY_TEAM.closer.name) {
        bullpen = { ...bullpen, awayCloserIn: true };
      }
    } catch (error) {
      // Corrupt / mismatched save — start fresh rather than crash the booth.
      // eslint-disable-next-line no-console
      console.warn("Could not restore saved game; starting fresh.", error);
      clearGameSave();
      state.reset();
      liveStats.reset();
      bullpen = createBullpenState();
      if (activeChallenge) {
        state.restore(activeChallenge.startingState(playerSide));
      }
    }
  } else if (activeChallenge) {
    state.restore(activeChallenge.startingState(playerSide));
  }

  const timingCoach = new TimingCoach(requireElement("timing-coach"), engine, () => difficulty);
  const timingCue = requireElement("timing-cue");
  const calGateHint = requireElement("cal-gate-hint");
  const skipCalibrationButton = requireElement<HTMLButtonElement>("skip-cal");
  let calibrationGateOpen = !calibration.isCalibrated && !prefs.calibrationSkipped;

  /** Rookie-plus assists and wider windows when playing through a screen reader. */
  function effectiveDifficulty(): DifficultyConfig {
    const base = difficulty;
    if (prefs.announceMode !== "screen-reader") return base;
    return {
      ...base,
      perfectWindowMs: Math.round(base.perfectWindowMs * 1.6),
      contactWindowMs: Math.round(base.contactWindowMs * 1.6),
      countableBeats: true,
      plateTick: true,
      spokenSwing: true,
    };
  }

  function assistWindows(base: { perfectWindowMs: number; contactWindowMs: number }): {
    perfectWindowMs: number;
    contactWindowMs: number;
  } {
    if (prefs.announceMode !== "screen-reader") return base;
    return {
      perfectWindowMs: Math.round(base.perfectWindowMs * 1.6),
      contactWindowMs: Math.round(base.contactWindowMs * 1.6),
    };
  }

  const sequencer = new PitchSequencer({
    engine,
    input,
    getCalibrationMs: () => calibration.offsetMs,
    getDifficulty: () => effectiveDifficulty(),
    rng,
    onTimingCue: (text) => {
      // Clear-then-set so assertive SR users hear repeats on consecutive pitches.
      timingCue.textContent = "";
      requestAnimationFrame(() => {
        timingCue.textContent = text === "swing" ? "Swing!" : "Release!";
      });
    },
    shouldSpeakTimingCue: () => prefs.announceMode !== "screen-reader",
  });

  let lastRoleBatting: boolean | null = null;

  // --- Crowd excitement: driven by game leverage, not a slider -------------
  // The slider still exists as a small manual trim (-2..+2) on top of the
  // computed value, so the player retains a control, but the primary driver is
  // the situation on the field: score margin, runners, outs, inning.
  const crowdSlider = requireElement<HTMLInputElement>("crowd-level");
  const crowdOut = requireElement<HTMLOutputElement>("crowd-level-out");
  let lastLeverage = 0;

  function currentExcitement(snapshot: GameSnapshot): ExcitementLevel {
    const leverage = computeLeverage(snapshot);
    lastLeverage = leverage;
    const bias = Number(crowdSlider.value);
    return clampLevel(excitementForLeverage(leverage) + bias);
  }

  crowdSlider.addEventListener("input", () => {
    crowdOut.textContent = crowdSlider.value;
    crowd.setExcitement(currentExcitement(state.snapshot()), 0.8);
  });

  const diagnostics = new Diagnostics(requireElement("diagnostics"), engine, () => calibration.offsetMs, () => ({
    leverage: lastLeverage,
    excitement: crowd.excitement,
  }));
  const timingDeltas: number[] = [];
  function recordTiming(deltaMs: number): void {
    timingDeltas.push(deltaMs);
    if (timingDeltas.length > 60) timingDeltas.shift();
    diagnostics.recordSwing(deltaMs);
  }
  const actionPad = new ActionPad(
    requireElement<HTMLButtonElement>("action-fab"),
    requireElement<HTMLButtonElement>("timing-action"),
    input,
  );
  const endGameCard = new EndGameCard(requireElement("end-card"));
  /** Last finished broadcast — fed to the BR-7 share sheet. */
  let lastShareMoment: BroadcastMoment | null = null;

  function currentThemeId(): string {
    return readArcadeBroadcastTheme() ?? prefs.broadcastTheme ?? "default";
  }

  function formatMeanTiming(): string {
    return timingDeltas.length === 0
      ? "No timed swings recorded."
      : `Timing: ${timingDeltas.length} swings, ${Math.round(timingDeltas.reduce((sum, value) => sum + value, 0) / timingDeltas.length)} ms average.`;
  }

  function captureShareMoment(args: {
    playerRuns: number;
    opponentRuns: number;
    innings: number;
    won: boolean;
    walkOff?: boolean;
    challengeTitle?: string;
    challengeSummary?: string;
    seriesLine?: string;
    seriesFinished?: boolean;
    modeLabel: string;
  }): BroadcastMoment {
    const tied = args.playerRuns === args.opponentRuns;
    const winnerShort = tied
      ? undefined
      : args.playerRuns > args.opponentRuns
        ? teamForSide(playerSide).shortName
        : teamForSide(playerSide === "home" ? "away" : "home").shortName;
    const dramaLine = buildDramaLine({
      won: args.won,
      tied,
      inning: args.innings,
      playerRuns: args.playerRuns,
      opponentRuns: args.opponentRuns,
      ...(args.walkOff !== undefined ? { walkOff: args.walkOff } : {}),
      ...(winnerShort !== undefined ? { winnerShort } : {}),
      ...(args.challengeTitle !== undefined ? { challengeTitle: args.challengeTitle } : {}),
      ...(args.challengeSummary !== undefined ? { challengeSummary: args.challengeSummary } : {}),
      ...(args.seriesLine !== undefined ? { seriesLine: args.seriesLine } : {}),
      ...(args.seriesFinished !== undefined ? { seriesFinished: args.seriesFinished } : {}),
    });
    const moment: BroadcastMoment = {
      playerRuns: args.playerRuns,
      opponentRuns: args.opponentRuns,
      innings: args.innings,
      won: args.won,
      dramaLine,
      timingSummary: formatMeanTiming(),
      modeLabel: args.modeLabel,
      ...(activeChallenge ? { challengeId: activeChallenge.id } : {}),
      seriesBo3:
        Boolean(activeSeries) ||
        sessionOptions.mode === "series" ||
        sessionOptions.mode === "playoff" ||
        (season?.unit === "series"),
      themeId: currentThemeId(),
      homeShort: HOME_TEAM.shortName,
      awayShort: AWAY_TEAM.shortName,
    };
    lastShareMoment = moment;
    return moment;
  }

  crowd.start();
  crowd.attachSamples();
  diagnostics.start();

  function paintBoard(): void {
    if (activeChallenge) {
      liveScore.setCampaignLine(
        `${activeChallenge.title}. ${activeChallenge.kind === "practice" ? `Cage ${practicePitchesThrown}/${activeChallenge.practicePitches ?? 10}, score ${practiceScore}.` : activeChallenge.rules}`,
      );
    } else if (activePlayoff) liveScore.setCampaignLine(activePlayoff.scoreLine());
    else if (season) liveScore.setCampaignLine(announceSeasonLine() ?? "");
    else if (activeSeries) liveScore.setCampaignLine(activeSeries.scoreLine());
    else liveScore.setCampaignLine("");
    const snapshot = state.snapshot();
    gameday.render(liveStats.snapshot(snapshot));
    liveScore.render(snapshot);
  }

  paintBoard();

  // Pre-game. The crowd bed is up so you know audio is alive, but no pitches are
  // thrown until you say so — calibration has to be reachable *before* the first
  // pitch, not squeezed in between two of them.
  readout.showMessage(
    calibration.offsetMs === 0
      ? "Calibrate latency first, then start when ready."
      : `Calibrated ${calibration.offsetMs >= 0 ? "+" : ""}${calibration.offsetMs.toFixed(0)} ms. Start when ready.`,
    calibration.offsetMs === 0 ? "warn" : null,
  );

  // --- Mixer (non-excitement controls) --------------------------------------
  const radioToggle = requireElement<HTMLInputElement>("radio-filter");
  radioToggle.checked = prefs.radioFilterDefault;
  engine.setRadioFilter(radioToggle.checked);
  radioToggle.addEventListener("change", () => {
    engine.setRadioFilter(radioToggle.checked);
    prefs = patchPrefs({ radioFilterDefault: radioToggle.checked });
  });

  const difficultySelect = requireElement<HTMLSelectElement>("difficulty");
  for (const id of DIFFICULTY_ORDER) {
    const option = difficultySelect.querySelector(`option[value="${id}"]`);
    if (option instanceof HTMLOptionElement && id === difficulty.id) option.selected = true;
  }

  function applyDifficulty(id: DifficultyId, announce: boolean): void {
    difficulty = getDifficulty(id);
    saveDifficultyId(id);
    selector.setDifficulty(difficulty);
    readout.setWindows(difficulty.perfectWindowMs, difficulty.contactWindowMs);
    timingCoach.setDifficulty(() => difficulty);
    if (announce) coachSpeak(difficulty.announce);
  }

  applyDifficulty(difficulty.id, false);

  difficultySelect.addEventListener("change", () => {
    const value = difficultySelect.value;
    if (!isDifficultyId(value)) return;
    applyDifficulty(value, true);
    persistNow();
  });

  const masterSlider = requireElement<HTMLInputElement>("master-gain");
  const masterOut = requireElement<HTMLOutputElement>("master-gain-out");
  masterSlider.addEventListener("input", () => {
    engine.setMasterLevel(Number(masterSlider.value) / 100);
    masterOut.textContent = masterSlider.value;
  });

  const bindBusLevel = (
    inputId: string,
    outputId: string,
    bus: "field" | "crowd" | "announcer",
    floor = 0,
  ): void => {
    const slider = requireElement<HTMLInputElement>(inputId);
    const output = requireElement<HTMLOutputElement>(outputId);
    const apply = (): void => {
      const level = Math.max(floor, Number(slider.value) / 100);
      engine.bus(bus).setLevel(level);
      // Keep color with play-by-play; Brian needs equal bus headroom.
      if (bus === "announcer") engine.bus("color").setLevel(level);
      output.textContent = String(Math.round(level * 100));
    };
    slider.addEventListener("input", apply);
    apply();
  };
  bindBusLevel("field-gain", "field-gain-out", "field", 0.4);
  bindBusLevel("crowd-bus-gain", "crowd-bus-gain-out", "crowd");
  bindBusLevel("booth-gain", "booth-gain-out", "announcer");

  const speechRate = requireElement<HTMLInputElement>("speech-rate");
  const speechRateOut = requireElement<HTMLOutputElement>("speech-rate-out");
  speechRate.value = String(Math.round(prefs.speechRate * 100));
  const applySpeechRate = (): void => {
    const value = Number(speechRate.value) / 100;
    setSpeechRateMultiplier(value);
    speechRateOut.textContent = `${Math.round(value * 100)}%`;
  };
  speechRate.addEventListener("input", () => {
    applySpeechRate();
    prefs = patchPrefs({ speechRate: Number(speechRate.value) / 100 });
  });
  applySpeechRate();

  const coachVerbosity = requireElement<HTMLSelectElement>("coach-verbosity");
  coachVerbosity.value = prefs.coachVerbosity;
  coachVerbosity.addEventListener("change", () => {
    if (coachVerbosity.value === "full" || coachVerbosity.value === "short" || coachVerbosity.value === "off") {
      prefs = patchPrefs({ coachVerbosity: coachVerbosity.value });
    }
  });

  const announceModeSelect = requireElement<HTMLSelectElement>("announce-mode");
  announceModeSelect.value = prefs.announceMode;
  announceModeSelect.addEventListener("change", () => {
    if (!isAnnounceMode(announceModeSelect.value)) return;
    prefs = patchPrefs({ announceMode: announceModeSelect.value });
    applyAnnounceMode();
    coachSpeak(
      prefs.announceMode === "screen-reader"
        ? "Announce mode: screen reader play-by-play. Timing windows are wider, and Swing stays in Controls."
        : prefs.announceMode === "both"
          ? "Announce mode: booth speech and screen reader log."
          : "Announce mode: booth speech.",
    );
    const eff = effectiveDifficulty();
    readout.setWindows(eff.perfectWindowMs, eff.contactWindowMs);
  });

  const boothVoiceSelect = requireElement<HTMLSelectElement>("booth-voice");
  boothVoiceSelect.value = prefs.boothVoice;
  boothVoiceSelect.addEventListener("change", () => {
    if (!isBoothVoice(boothVoiceSelect.value)) return;
    prefs = patchPrefs({ boothVoice: boothVoiceSelect.value });
    if (prefs.boothVoice === "sampled") {
      void sampledBackend.load();
      void castBackend.warmUp();
    }
    coachSpeak(
      prefs.boothVoice === "sampled"
        ? "Booth voice: live cast with player names. Samples if the cast line fails."
        : "Booth voice: system speech.",
    );
  });

  // --- Transport -----------------------------------------------------------
  /**
   * `loopActive` is the re-entry guard, and it is load-bearing. Three things can
   * ask the game to stop and start again — the pause button, calibration, and the
   * timing harness — and two overlapping loops would fight over the sequencer,
   * which rejects a second pitch while one is live. Requesting a stop is therefore
   * always asynchronous: set the flag, then wait for the loop to actually exit.
   */
  let loopActive = false;
  let stopRequested = false;
  /** Set the instant a play ends the game. Distinct from `stopRequested` because
   *  the transport button needs to know *why* it stopped: "Resume" vs "New Game". */
  let gameOver = false;
  let sessionStartedAt = performance.now();

  function persistNow(): void {
    if (gameOver || state.gameOver) {
      clearGameSave();
      return;
    }
    const campaign = campaignBlob();
    writeGameSave(
      buildGameSave({
        playerSide,
        difficultyId: difficulty.id,
        session: sessionOptions,
        game: state.exportPersist(),
        live: liveStats.exportPersist(),
        bullpen,
        ...(campaign !== undefined ? { campaign } : {}),
      }),
    );
    if (season) {
      if (season.unit === "series" && activeSeries && !activeSeries.isComplete()) {
        season = { ...season, currentSeries: activeSeries.toCampaign() };
      }
      writeSeason(season);
    }
    if (activePlayoff) writePlayoff(activePlayoff);
    else if (activeSeries && !season) writeSeries(activeSeries);
  }

  /** Cancel in-flight work and flush a between-pitches save (phone call / tab hide). */
  function saveAndSuspend(): void {
    stopRequested = true;
    pitchCall.cancelWait();
    sequencer.cancel();
    persistNow();
  }

  const onPageHide = (): void => {
    saveAndSuspend();
  };
  const onVisibility = (): void => {
    if (document.visibilityState === "hidden") saveAndSuspend();
  };
  window.addEventListener("pagehide", onPageHide);
  document.addEventListener("visibilitychange", onVisibility);

  renderGameState = (): string => {
    const snapshot = state.snapshot();
    return JSON.stringify({
      mode: gameOver ? "game-over" : loopActive ? "playing" : "ready",
      coordinateSystem: "Audio-first game; pitch location is described as horizontal stereo pan and vertical brightness.",
      playerSide,
      playerRole: isPlayerBatting(snapshot, playerSide) ? "batting" : "pitching",
      inning: snapshot.inning,
      half: snapshot.half,
      count: { balls: snapshot.balls, strikes: snapshot.strikes, outs: snapshot.outs },
      score: snapshot.score,
      bases: snapshot.bases,
      batter: snapshot.batter,
      pitcher: snapshot.pitcher,
      difficulty: difficulty.id,
      challengeId: sessionOptions.challengeId,
      challengeOutcome: lastChallengeOutcome,
      bullpen: {
        humanCallUsed: bullpen.humanCallUsed,
        homeCloserIn: bullpen.homeCloserIn,
        awayCloserIn: bullpen.awayCloserIn,
      },
      controls: { primary: "Tap or Space", transport: "next-pitch button", fullscreen: "F" },
    });
  };

  const transport = requireElement<HTMLButtonElement>("next-pitch");

  function fieldingSideOf(snapshot: GameSnapshot): "home" | "away" {
    return snapshot.half === "top" ? "home" : "away";
  }

  function syncCallCloserButton(snapshot: GameSnapshot): void {
    const batting = isPlayerBatting(snapshot, playerSide);
    const humanPitching =
      !batting &&
      sessionOptions.mode !== "practice" &&
      sessionOptions.roleLock !== "bat" &&
      !gameOver;
    const side = playerSide;
    const pitches = pitchesForSide(bullpen, side);
    const available =
      humanPitching &&
      canHumanCallCloser({
        inning: snapshot.inning,
        pitches,
        regulationInnings: state.scheduledInnings,
        closerAlreadyIn: closerInForSide(bullpen, side),
        humanCallUsed: bullpen.humanCallUsed,
      });
    const penEmpty = humanPitching && (bullpen.humanCallUsed || closerInForSide(bullpen, side));
    callCloserBtn.disabled = !humanPitching || (!available && !penEmpty);
    callCloserBtn.setAttribute("aria-disabled", callCloserBtn.disabled ? "true" : "false");
    if (!humanPitching) {
      callCloserBtn.setAttribute(
        "aria-label",
        "Call the closer — available when you are pitching late, once per game",
      );
      callCloserHint.textContent =
        "Late innings: bring in your closer once per game (Controls rail).";
    } else if (penEmpty && !available) {
      callCloserBtn.setAttribute("aria-label", "Call the closer — pen is empty");
      callCloserHint.textContent = "Pen is empty — you've already made your call.";
    } else if (available) {
      callCloserBtn.setAttribute(
        "aria-label",
        "Call the closer — bring in your late-inning arm, once per game",
      );
      callCloserHint.textContent = "Closer ready — activate to go to the pen.";
    } else {
      callCloserBtn.setAttribute(
        "aria-label",
        "Call the closer — available when the starter is laboring or in the late innings",
      );
      callCloserHint.textContent =
        "Available when the starter is laboring, or from the 8th (or final inning) on.";
    }
  }

  /**
   * Swap the fielding club's starter for its named closer. Resets fatigue, updates
   * live-score / box, station-ID sting, booth entry line.
   */
  function bringInCloser(side: "home" | "away", byHuman: boolean): void {
    if (closerInForSide(bullpen, side)) return;
    const team = side === "home" ? HOME_TEAM : AWAY_TEAM;
    const closer = team.closer;
    bullpen = enterCloser(bullpen, side, byHuman);
    state.setPitcher(side, closer);
    liveStats.setPitcher(side, closer.name);
    selector.setPitcher(pitcherRatingsOf(closer));
    paintBoard();
    persistNow();
    syncCallCloserButton(state.snapshot());

    const entry = closerEntryLine(closer.name, team.shortName, byHuman);
    coachSpeak(entry, { energy: 0.5 });
    queue.say(
      { id: "bullpen.closer", text: entry, speaker: "announcer", energy: 0.55 },
      { notBefore: engine.currentTime, priority: PRIORITY.playByPlay },
    );
    queue.say(buildStationIdLine(rng), {
      notBefore: engine.currentTime + 0.35,
      priority: PRIORITY.utility,
    });
  }

  const callCloserBtn = requireElement<HTMLButtonElement>("call-closer");
  const callCloserHint = requireElement("call-closer-hint");

  function syncRoleChrome(
    snapshot: GameSnapshot,
    options: { setTransport?: boolean; announceRoleChange?: boolean } = {},
  ): void {
    const batting = isPlayerBatting(snapshot, playerSide);
    timingCoach.setRole(batting ? "bat" : "pitch");
    actionPad.setRole(batting ? "bat" : "pitch");
    const roleAllowsPad =
      !gameOver &&
      !calibrationGateOpen &&
      sessionOptions.mode !== "practice" &&
      (sessionOptions.roleLock === "both" ||
        (sessionOptions.roleLock === "bat" && batting) ||
        (sessionOptions.roleLock === "pitch" && !batting));
    actionPad.setEnabled(roleAllowsPad);
    spaceHint.textContent = batting
      ? "During the pitch: activate Swing (or press Space) on beat five. Count four, swing on five."
      : "During the windup: activate Release (or press Space) on beat four, then the pitch flies.";
    pitchCall.setActive(!batting && sessionOptions.roleLock !== "bat");
    syncCallCloserButton(snapshot);
    if (options.setTransport && !gameOver) {
      transport.textContent = batting ? "Start at-bat" : "Ready to pitch";
    }
    if (options.announceRoleChange !== false && lastRoleBatting !== null && lastRoleBatting !== batting) {
      coachSpeak(roleAnnounce(batting), { energy: 0.4 });
    }
    lastRoleBatting = batting;
  }

  function applyCalibrationGate(): void {
    skipCalibrationButton.hidden = !calibrationGateOpen;
    calGateHint.hidden = !calibrationGateOpen;
    transport.disabled = calibrationGateOpen;
    if (calibrationGateOpen) {
      skipCalibrationButton.classList.add("primary");
      skipCalibrationButton.classList.remove("secondary");
      readout.showMessage("Calibrate first, or choose Skip calibration — start playing.", "warn");
    } else {
      skipCalibrationButton.classList.remove("primary");
      skipCalibrationButton.classList.add("secondary");
    }
  }

  const sideLine = announcePlayerSide(playerSide);
  const seasonOpen = announceSeasonLine();
  const playoffOpen = activePlayoff
    ? resumeSave
      ? activePlayoff.scoreLine()
      : activePlayoff.playoffOpenLine()
    : null;
  const seriesOpen = activeSeries
    ? resumeSave
      ? activeSeries.scoreLine()
      : activeSeries.seriesOpenLine()
    : null;
  const challengeOpen = activeChallenge
    ? `${activeChallenge.situationLine(playerSide)} ${activeChallenge.rules}`
    : null;
  if (resumeSave && !state.gameOver) {
    const campaignLine = challengeOpen ?? seasonOpen ?? playoffOpen ?? seriesOpen;
    coachSpeak(
      `Resuming broadcast. ${describeGameSave(resumeSave)}.${campaignLine ? ` ${campaignLine}` : ""} ${sideLine}`,
      { energy: 0.45 },
    );
    persistNow();
  } else {
    const campaignLine = challengeOpen ?? seasonOpen ?? playoffOpen ?? seriesOpen;
    coachSpeak(
      `${sideLine} ${difficulty.announce}${campaignLine ? ` ${campaignLine}` : ""}`,
      { energy: 0.4 },
    );
    persistNow();
  }
  applyCalibrationGate();
  syncRoleChrome(state.snapshot(), { setTransport: true, announceRoleChange: false });
  paintBoard();

  // Land keyboard/SR focus in the control rail after leaving the gate.
  queueMicrotask(() => {
    const cal = requireElement<HTMLButtonElement>("calibrate");
    if (calibrationGateOpen) skipCalibrationButton.focus();
    else if (!calibration.isCalibrated) cal.focus();
    else transport.focus();
  });

  const calibrateButton = requireElement<HTMLButtonElement>("calibrate");
  const calibrationTapZone = requireElement("cal-tap-zone");

  skipCalibrationButton.addEventListener("click", () => {
    prefs = patchPrefs({ calibrationSkipped: true });
    calibrationGateOpen = false;
    applyCalibrationGate();
    syncRoleChrome(state.snapshot());
    readout.showMessage("Calibration skipped. Start at-bat is ready.", "warn");
    coachSpeak("Calibration skipped. Start at-bat is ready.", { energy: 0.35 });
    queueMicrotask(() => transport.focus());
    if (sessionOptions.mode === "practice" && !loopActive) void runLoop();
  });

  /**
   * Stop now, not at the end of the current pitch.
   *
   * Cancelling the live pitch cuts the ball out of the air and rejects the
   * sequencer promise, which drops the loop out immediately. Waiting politely for
   * the pitch to reach the plate meant up to two seconds of nothing happening
   * after you clicked Pause, which reads as a dead button.
   */
  async function stopLoop(): Promise<void> {
    stopRequested = true;
    pitchCall.cancelWait();
    sequencer.cancel();
    await waitForIdle(() => !loopActive);
    // Whatever the booth was still going to say about a pitch we just abandoned
    // is no longer worth hearing.
    queue.clear();
    cancelAllSpeech();
    persistNow();
    syncRoleChrome(state.snapshot(), { setTransport: true });
  }

  function resetGame(): void {
    state.reset();
    liveStats.reset();
    bullpen = createBullpenState();
    gameOver = false;
    sessionStartedAt = performance.now();
    stopRequested = false;
    lastRoleBatting = null;
    lastChallengeOutcome = null;
    practicePitchesThrown = 0;
    practiceScore = 0;
    radioLog.clear();
    diagnostics.reset();
    timingDeltas.length = 0;
    queue.clear();
    cancelAllSpeech();
    if (activeChallenge) {
      state.restore(activeChallenge.startingState(playerSide));
    }
    paintBoard();
    crowd.setExcitement(currentExcitement(state.snapshot()), 1.5);
    const open = activeChallenge
      ? `${activeChallenge.situationLine(playerSide)} ${activeChallenge.rules}`
      : "New game. Start when ready.";
    readout.showMessage(open, null);
    if (activeChallenge) {
      coachSpeak(open, { energy: 0.45 });
    }
    transport.disabled = false;
    syncRoleChrome(state.snapshot(), { setTransport: true, announceRoleChange: false });
    endGameCard.hide();
    persistNow();
  }

  function startNextSeasonGame(): void {
    if (sessionOptions.campaignKind === "season" && !season) {
      season = createSeason({
        scheduleLength: sessionOptions.seasonSchedule,
        playerSide,
        length: sessionOptions.length,
        roleLock: sessionOptions.roleLock,
        difficultyId: difficulty.id,
        unit: sessionOptions.seasonUnit,
      });
      writeSeason(season);
      activeSeries = season.unit === "series" ? seasonSeriesState(season) : null;
    } else if (season?.unit === "series") {
      season = ensureSeasonSeries(season);
      activeSeries = seasonSeriesState(season);
      writeSeason(season);
    }
    resetGame();
    const line = announceSeasonLine();
    if (line) {
      coachSpeak(line, { energy: 0.45 });
      readout.showMessage(line, null);
    }
  }

  /** Continue a Best-of-3 after a game, or rematch after the series ends. */
  function continueOrRematchSeries(): void {
    // Season-of-series: never start a standalone series shell.
    if (season?.unit === "series") {
      if (isSeasonComplete(season)) {
        season = createSeason({
          scheduleLength: sessionOptions.seasonSchedule,
          playerSide,
          length: sessionOptions.length,
          roleLock: sessionOptions.roleLock,
          difficultyId: difficulty.id,
          unit: "series",
        });
        writeSeason(season);
      } else {
        season = ensureSeasonSeries(season);
        writeSeason(season);
      }
      activeSeries = seasonSeriesState(season);
      resetGame();
      const line = announceSeasonLine() ?? activeSeries?.seriesOpenLine() ?? "";
      if (line) {
        coachSpeak(line, { energy: 0.45 });
        readout.showMessage(line, null);
      }
      return;
    }
    if (!activeSeries || activeSeries.isComplete()) {
      activeSeries = SeriesState.create({
        playerSide,
        length: sessionOptions.length,
        roleLock: sessionOptions.roleLock,
        difficultyId: difficulty.id,
      });
      writeSeries(activeSeries);
      resetGame();
      coachSpeak(activeSeries.seriesOpenLine(), { energy: 0.45 });
      readout.showMessage(activeSeries.seriesOpenLine(), null);
      return;
    }
    resetGame();
    const line = activeSeries.scoreLine();
    coachSpeak(line, { energy: 0.4 });
    readout.showMessage(line, null);
  }

  /** Continue the current playoff series, or start a fresh bracket after the clinch. */
  function continueOrRematchPlayoff(): void {
    if (!activePlayoff || activePlayoff.isComplete()) {
      activePlayoff = PlayoffState.create({
        playerSide,
        length: sessionOptions.length,
        roleLock: sessionOptions.roleLock,
        difficultyId: difficulty.id,
        format: sessionOptions.playoffFormat,
      });
      writePlayoff(activePlayoff);
      resetGame();
      coachSpeak(activePlayoff.playoffOpenLine(), { energy: 0.45 });
      readout.showMessage(activePlayoff.playoffOpenLine(), null);
      return;
    }
    resetGame();
    const line = activePlayoff.scoreLine();
    coachSpeak(line, { energy: 0.4 });
    readout.showMessage(line, null);
  }

  endGameCard.onAction((action) => {
    if (action === "share") {
      const moment = lastShareMoment;
      if (!moment) {
        coachSpeak("Nothing to share yet — finish a broadcast first.", { energy: 0.35 });
        return;
      }
      openBroadcastShareSheet({
        moment,
        href: window.location.href,
        onOpened: () => {
          const line = shareBoothLine();
          coachSpeak(line, { energy: 0.4 });
          queue.say(
            { id: "share.open", text: line, speaker: "announcer", energy: 0.35 },
            { notBefore: engine.currentTime, priority: PRIORITY.utility },
          );
        },
      });
      return;
    }
    if (action === "new") {
      if (activePlayoff) {
        continueOrRematchPlayoff();
        return;
      }
      if (activeSeries) {
        continueOrRematchSeries();
        return;
      }
      if (sessionOptions.campaignKind === "season") {
        startNextSeasonGame();
        return;
      }
      resetGame();
      return;
    }
    if (action === "difficulty") {
      endGameCard.hide();
      difficultySelect.focus();
      return;
    }
    const feedback = document.getElementById("cade-feedback-open") ??
      document.querySelector<HTMLElement>("[data-feedback-open], #feedback-open");
    if (feedback instanceof HTMLElement) feedback.click();
    else window.focus();
  });

  requireElement<HTMLButtonElement>("announce-situation").addEventListener("click", () => {
    const snapshot = state.snapshot();
    const line = `${formatScore(snapshot.score, snapshot.homeTeam, snapshot.awayTeam)}. ${snapshot.half} of the ${snapshot.inning}${ordinal(snapshot.inning)}. ${snapshot.outs} out${snapshot.outs === 1 ? "" : "s"}, count ${formatCount(snapshot.balls, snapshot.strikes)}. ${formatBases(snapshot.bases)}.`;
    queue.say({ id: "situation.manual", text: line, speaker: "announcer", energy: 0.3 }, {
      notBefore: engine.currentTime,
      priority: PRIORITY.playByPlay,
    });
  });

  callCloserBtn.addEventListener("click", () => {
    callCloserBtn.blur();
    const snapshot = state.snapshot();
    const batting = isPlayerBatting(snapshot, playerSide);
    if (batting || sessionOptions.mode === "practice" || gameOver) {
      coachSpeak("Call the closer is available when you're pitching.", { energy: 0.35 });
      return;
    }
    const side = playerSide;
    if (bullpen.humanCallUsed || closerInForSide(bullpen, side)) {
      const empty = penEmptyLine();
      coachSpeak(empty, { energy: 0.4 });
      queue.say(
        { id: "bullpen.empty", text: empty, speaker: "announcer", energy: 0.35 },
        { notBefore: engine.currentTime, priority: PRIORITY.playByPlay },
      );
      return;
    }
    const pitches = pitchesForSide(bullpen, side);
    if (
      !canHumanCallCloser({
        inning: snapshot.inning,
        pitches,
        regulationInnings: state.scheduledInnings,
        closerAlreadyIn: false,
        humanCallUsed: false,
      })
    ) {
      coachSpeak(
        "Not yet — wait until the starter is laboring, or the late innings.",
        { energy: 0.35 },
      );
      return;
    }
    bringInCloser(side, true);
  });

  transport.addEventListener("click", () => {
    // Drop focus, or the button stays keyboard-active and steals the spacebar's
    // visual affordance from the swing.
    transport.blur();
    if (gameOver) {
      if (activePlayoff) {
        continueOrRematchPlayoff();
        return;
      }
      if (activeSeries) {
        continueOrRematchSeries();
        return;
      }
      if (sessionOptions.campaignKind === "season") {
        startNextSeasonGame();
        return;
      }
      resetGame();
      return;
    }
    if (loopActive) {
      void stopLoop();
      return;
    }
    if (calibrationGateOpen) {
      readout.showMessage("Calibrate first, or choose Skip calibration — start playing.", "warn");
      skipCalibrationButton.focus();
      return;
    }
    stopRequested = false;
    void runLoop();
  });

  calibrateButton.addEventListener("click", () => {
    if (calibration.isRunning) return;
    calibrateButton.blur();
    calibrateButton.disabled = true;
    const wasRunning = loopActive;
    void (async () => {
      // Calibration owns the spacebar and the field bus, so the game has to be
      // fully stopped first — not merely asked to stop.
      await stopLoop();
      readout.showMessage("Tap or press SPACE on each click...", "warn");
      calibrationTapZone.hidden = false;
      requireElement<HTMLButtonElement>("cal-tap-target").focus();
      await calibration.run();
      calibrationTapZone.hidden = true;
      diagnostics.reset();
      calibrateButton.disabled = false;
      stopRequested = false;

      const offset = calibration.offsetMs;
      readout.showMessage(
        offset === 0
          ? "Calibration didn't register enough taps — try again."
          : `Calibrated ${offset >= 0 ? "+" : ""}${offset.toFixed(0)} ms.`,
        offset === 0 ? "warn" : null,
      );
      if (calibration.isCalibrated) {
        calibrationGateOpen = false;
        applyCalibrationGate();
        syncRoleChrome(state.snapshot());
        coachSpeak("Calibration complete. Start at-bat is ready.", { energy: 0.35 });
        queueMicrotask(() => transport.focus());
        if (sessionOptions.mode === "practice" && !wasRunning) void runLoop();
      }

      // Resume only if we interrupted a live at-bat, and the game isn't over.
      if (wasRunning && !gameOver) void runLoop();
    })();
  });

  installTimingHarness({
    engine,
    input,
    sequencer,
    getCalibrationMs: () => calibration.offsetMs,
    pause: stopLoop,
  });
  if (sessionOptions.mode === "practice" && !calibrationGateOpen) void runLoop();

  // --- The loop ------------------------------------------------------------
  async function runLoop(): Promise<void> {
    if (sessionOptions.mode === "practice") {
      await runPracticeLoop();
      return;
    }
    if (loopActive || gameOver) return;
    loopActive = true;
    transport.textContent = "Pause";
    transport.disabled = false;
    try {
      while (!stopRequested) {
        try {
          const gap = await throwOne();
          if (stopRequested || gameOver) break;
          // Hold for the longer of the minimum radio gap and "booth is done talking".
          await waitForBroadcastGap(gap);
        } catch {
          // A cancelled pitch (calibration, teardown) simply ends the loop.
          break;
        }
      }
    } finally {
      loopActive = false;
      pitchCall.cancelWait();
      syncRoleChrome(state.snapshot(), { setTransport: false });
      transport.textContent = gameOver
        ? activeChallenge
          ? "Retry challenge"
          : activePlayoff && !activePlayoff.isComplete()
          ? "Next game"
          : activePlayoff
            ? "New Playoff"
            : activeSeries && !activeSeries.isComplete()
              ? "Next game"
              : activeSeries
                ? "New Series"
                : season && !isSeasonComplete(season)
                  ? "Next game"
                  : sessionOptions.campaignKind === "season"
                    ? "New Season"
                    : "New Game"
        : "Resume";
      transport.disabled = false;
      if (!gameOver) crowd.setExcitement(currentExcitement(state.snapshot()), 1.5);
    }
  }

  async function runPracticeLoop(): Promise<void> {
    if (loopActive || calibrationGateOpen || gameOver) return;
    loopActive = true;
    transport.textContent = "Pause";
    transport.disabled = false;
    actionPad.setEnabled(true);
    try {
      while (!stopRequested && !gameOver) {
        const gap = await throwPracticePitch();
        if (stopRequested || gameOver) break;
        await waitForBroadcastGap(gap);
      }
    } catch {
      // Pause and calibration intentionally cancel the live practice pitch.
    } finally {
      loopActive = false;
      input.disarm();
      actionPad.setEnabled(false);
      transport.textContent = gameOver && activeChallenge ? "Retry challenge" : "Resume";
      transport.disabled = false;
    }
  }

  async function throwPracticePitch(): Promise<number> {
    selector.setPitcher(pitcherRatingsOf(state.currentPitcher()));
    selector.setDifficulty(getDifficulty("rookie"));
    const call = selector.select(0, 0);
    const pressesBefore = input.ignoredPresses;
    const result = await sequencer.throwPitch(call.profile, call.location, {
      onScheduled: (timeline) => timingCoach.arm(timeline),
      windows: {
        perfectWindowMs: difficulty.perfectWindowMs,
        contactWindowMs: difficulty.contactWindowMs,
      },
    });
    timingCoach.clear();
    if (result.judgment.swung) {
      recordTiming(result.judgment.deltaMs);
      readout.showSwing(result.judgment.deltaMs, result.judgment.contact);
    } else {
      readout.showTake(input.ignoredPresses - pressesBefore);
    }
    if (activeChallenge?.kind === "practice") {
      practicePitchesThrown += 1;
      const raw = result.judgment.swung ? result.judgment.contact : "take";
      const contact =
        raw === "solid" || raw === "weak" || raw === "miss" || raw === "take" ? raw : "miss";
      practiceScore += scorePracticeContact(contact);
      paintBoard();
      persistNow();
      const outcome = evaluatePracticeCage(activeChallenge, practicePitchesThrown, practiceScore);
      if (outcome) {
        finishChallenge(outcome, state.snapshot());
      }
    }
    if (prefs.coachVerbosity !== "off") {
      const hand = batterHandForAb(state.snapshot().batter, state.snapshot().pitcher);
      const loc = describeLocation(call.location, hand);
      coachSpeak(
        prefs.coachVerbosity === "short" ? loc : `Fastball ${loc}.`,
        { speaker: "color", energy: 0.3, interrupt: false },
      );
    }
    return BETWEEN_PITCHES_SEC;
  }

  function finishChallenge(outcome: ChallengeOutcome, after: GameSnapshot): void {
    if (gameOver) return;
    lastChallengeOutcome = outcome;
    if (!state.gameOver) state.forceEnd();
    gameOver = true;
    stopRequested = true;
    clearGameSave();
    const playerRuns = after.score[playerSide];
    const opponentRuns = after.score[playerSide === "home" ? "away" : "home"];
    const meanTiming = formatMeanTiming();
    coachSpeak(outcome.summary, { energy: 0.5 });
    queue.say(
      { id: "challenge.final", text: outcome.summary, speaker: "announcer", energy: 0.5 },
      { notBefore: engine.currentTime + 0.2, priority: PRIORITY.playByPlay },
    );
    captureShareMoment({
      playerRuns,
      opponentRuns,
      innings: after.inning,
      won: outcome.won,
      challengeTitle: outcome.title,
      challengeSummary: outcome.summary,
      modeLabel: describeSession(sessionOptions),
    });
    endGameCard.show({
      won: outcome.won,
      playerRuns,
      opponentRuns,
      innings: after.inning,
      timingSummary: meanTiming,
      seriesSummary: outcome.summary,
      modeLabel: describeSession(sessionOptions),
      primaryLabel: "Retry challenge",
      titleOverride: outcome.title,
    });
    window.dispatchEvent(
      new CustomEvent("baseball-radio-game-over", {
        detail: {
          playerRuns,
          opponentRuns,
          innings: after.inning,
          won: outcome.won,
          challengeId: activeChallenge?.id,
          challengeWon: outcome.won,
          durationMs: Math.max(0, Math.round(performance.now() - sessionStartedAt)),
        },
      }),
    );
    paintBoard();
    transport.textContent = "Retry challenge";
  }

  /**
   * Wait until the booth has finished its between-pitch fill *and* at least
   * `minSec` has elapsed since the pitch resolved. Polls so Pause/calibration
   * can break out without sitting on a single long sleep.
   */
  async function waitForBroadcastGap(minSec: number): Promise<void> {
    const earliest = performance.now() + minSec * 1000;
    while (!stopRequested) {
      const boothRemainingMs = Math.max(0, (queue.busyUntil - engine.currentTime) * 1000);
      const minRemainingMs = earliest - performance.now();
      if (boothRemainingMs <= 40 && minRemainingMs <= 0) break;
      const wait = Math.min(120, Math.max(40, boothRemainingMs, minRemainingMs));
      await sleep(wait);
    }
    if (!stopRequested) await sleep(BOOTH_CLEAR_PAD_MS);
  }

  /** @returns Minimum seconds to hold before the next pitch (inning breaks get longer). */
  async function throwOne(): Promise<number> {
    let before = state.snapshot();
    const leverage = computeLeverage(before);
    const playerBatting = isPlayerBatting(before, playerSide);
    syncRoleChrome(before, { setTransport: false });
    let nextGap = BETWEEN_PITCHES_SEC;

    crowd.setExcitement(currentExcitement(before), 0.8);

    // AI manager: when the human bats, auto-call the closer in a late tired frame.
    if (playerBatting && sessionOptions.mode !== "practice") {
      const aiSide = fieldingSideOf(before);
      if (
        shouldAiCallCloser({
          inning: before.inning,
          pitches: pitchesForSide(bullpen, aiSide),
          regulationInnings: state.scheduledInnings,
          closerAlreadyIn: closerInForSide(bullpen, aiSide),
        })
      ) {
        bringInCloser(aiSide, false);
        before = state.snapshot();
        await sleep(700);
        if (stopRequested) return nextGap;
      }
    }

    // A fresh plate appearance is exactly the pitches where the count reads 0-0 —
    // `GameState` resets the count at that boundary and nowhere else, so it's a
    // reliable signal with no extra bookkeeping needed here.
    const isNewBatter = before.balls === 0 && before.strikes === 0;
    if (isNewBatter) {
      const situation = buildSituationLine(before, leverage, before.homeTeam, before.awayTeam, rng);
      if (situation) {
        const sitEnd = queue.say(situation, {
          notBefore: engine.currentTime + 0.12,
          priority: PRIORITY.playByPlay,
        });
        // Let the batter intro land before the windup pulse — radio does the
        // same, then the pitcher comes set.
        const introMs = Math.min(9000, Math.max(0, (sitEnd - engine.currentTime) * 1000 - 150));
        await sleep(introMs);
        if (stopRequested) return nextGap;
      }
    }

    const batterPlayer = state.currentBatter();
    const pitcherPlayer = state.currentPitcher();
    const batterRatings = batterRatingsOf(batterPlayer);
    const fieldSide = fieldingSideOf(before);
    const starterFatigued =
      !closerInForSide(bullpen, fieldSide) &&
      isStarterFatigued(pitchesForSide(bullpen, fieldSide), before.inning);
    const pitcherRatings = applyFatigueToRatings(pitcherRatingsOf(pitcherPlayer), starterFatigued);
    selector.setPitcher(pitcherRatings);

    let call: PitchCall;
    let judgment: SwingJudgment;
    let contactTime: number;
    let followUpTime: number;
    let profileForStats: PitchCall["profile"];
    let locationForStats: PitchCall["location"];

    const humanBatting = playerBatting && sessionOptions.roleLock !== "pitch";
    const humanPitching = !playerBatting && sessionOptions.roleLock !== "bat";

    if (humanBatting) {
      call = selector.select(before.balls, before.strikes);

      // Log-only delivery cue. Preempts leftover colour so it can't spill into the windup.
      queue.say(buildDeliveryCall(before.pitcher, rng), {
        notBefore: engine.currentTime + 0.05,
        priority: PRIORITY.playByPlay,
        preempt: true,
      });

      const batterWindows = assistWindows(
        windowsForBatter(
          {
            perfectWindowMs: difficulty.perfectWindowMs,
            contactWindowMs: difficulty.contactWindowMs,
          },
          batterRatings,
        ),
      );

      const pressesBefore = input.ignoredPresses;
      let result: PitchResult;
      try {
        result = await sequencer.throwPitch(call.profile, call.location, {
          onScheduled: (timeline) => timingCoach.arm(timeline),
          windows: batterWindows,
        });
      } catch (error) {
        timingCoach.clear();
        throw error;
      }
      timingCoach.clear();

      if (result.judgment.swung) {
        recordTiming(result.judgment.deltaMs);
        readout.showSwing(result.judgment.deltaMs, result.judgment.contact);
      } else {
        readout.showTake(input.ignoredPresses - pressesBefore);
      }

      judgment = result.judgment;
      contactTime = result.contactTime;
      followUpTime = result.followUpTime;
      profileForStats = call.profile;
      locationForStats = call.location;
    } else {
      if (humanPitching) {
        pitchCall.setBatterHand(batterHandForAb(before.batter, before.pitcher));
        pitchCall.setActive(true);
        try {
          call = await pitchCall.waitForCall();
        } catch (error) {
          throw error;
        }
        if (stopRequested) return nextGap;

        // Human call pad chooses type/location; scale velo/flight to the starter.
        call = {
          profile: profileForPitcher(call.profile.type, pitcherRatings),
          location: call.location,
        };

        const callLine = pitchCall.describeCurrent();
        if (prefs.coachVerbosity !== "off") {
          coachSpeak(callLine, { energy: 0.35 });
        } else {
          difficultyAnnounce.textContent = callLine;
        }
      } else {
        // Role lock gives this half to the AI. `throwPitchAsPitcher` auto-releases
        // when no input arrives, so this preserves the pitcher-side audio path.
        call = selector.select(before.balls, before.strikes);
      }

      queue.say(buildDeliveryCall(before.pitcher, rng), {
        notBefore: engine.currentTime + 0.05,
        priority: PRIORITY.playByPlay,
        preempt: true,
      });

      let pitcherResult: PitcherResult;
      try {
        pitcherResult = await sequencer.throwPitchAsPitcher(call.profile, call.location, {
          onScheduled: (timeline) => timingCoach.arm(timeline),
        });
      } catch (error) {
        timingCoach.clear();
        throw error;
      }
      timingCoach.clear();

      readout.showRelease(pitcherResult.release.deltaMs, pitcherResult.release.autoReleased);
      recordTiming(pitcherResult.release.deltaMs);

      // AI uses its own windows (see aiBatterWindows) — not human Rookie assists.
      judgment = decideBatterSwing({
        balls: before.balls,
        strikes: before.strikes,
        profile: pitcherResult.finalProfile,
        location: pitcherResult.finalLocation,
        perceivedPlateMs: pitcherResult.perceivedPlateMs,
        difficulty,
        batter: batterRatings,
        pitcher: pitcherRatings,
        rng,
      });

      playPitchAftermath(
        engine,
        judgment,
        pitcherResult.contactTime,
        pitcherResult.finalProfile.velocityMph,
        pitcherResult.cutFlight,
      );

      contactTime = pitcherResult.contactTime;
      followUpTime = pitcherResult.followUpTime;
      profileForStats = pitcherResult.finalProfile;
      locationForStats = pitcherResult.finalLocation;
      call = { profile: pitcherResult.finalProfile, location: pitcherResult.finalLocation };
    }

    const play = resolvePlay(judgment, rng, batterRatings);
    const report = state.applyPlay(play);
    const after = state.snapshot();

    const batterHand = batterHandForAb(before.batter, before.pitcher);
    if (difficulty.id === "rookie" && prefs.coachVerbosity !== "off") {
      const loc = describeLocation(locationForStats, batterHand);
      coachSpeak(
        prefs.coachVerbosity === "short" ? loc : `That pitch was ${loc}.`,
        { speaker: "color", energy: 0.3, interrupt: false },
      );
    }

    liveStats.recordPitch({
      before,
      after,
      report,
      play,
      profile: profileForStats,
      location: locationForStats,
      inZone: isInStrikeZone(locationForStats),
    });

    // Fatigue bookkeeping for the arm that just threw.
    const threwSide = fieldingSideOf(before);
    bullpen = recordPitchThrown(bullpen, threwSide);
    if (
      !closerInForSide(bullpen, threwSide) &&
      isStarterFatigued(pitchesForSide(bullpen, threwSide), after.inning) &&
      !fatigueAnnouncedForSide(bullpen, threwSide)
    ) {
      bullpen = markFatigueAnnounced(bullpen, threwSide);
      const fade = fatigueBoothLine(before.pitcher, pitchesForSide(bullpen, threwSide));
      queue.say(
        { id: "bullpen.fatigue", text: fade, speaker: "color", energy: 0.4 },
        { notBefore: engine.currentTime + 0.2, priority: PRIORITY.color },
      );
    }
    syncCallCloserButton(after);

    paintBoard();
    if (report.gameEnded) {
      clearGameSave();
    } else {
      persistNow();
    }
    if (report.inningEnded && !report.gameEnded) {
      syncRoleChrome(after, { setTransport: false });
    }

    // Umpire first — quiet field bark for place, spoken words through the queue.
    const ump = umpireCallFor(play, report.outcome);
    let voiceFloor = followUpTime;
    if (ump) {
      playUmpireCall(engine, ump, followUpTime);
      const umpPhrase: Phrase = {
        id: `umpire.${ump}`,
        text: UMPIRE_WORDS[ump],
        speaker: "umpire",
        energy: ump === "strike-three" ? 0.95 : 0.7,
      };
      // Same priority as play-by-play so the result call's cancelBelow doesn't
      // wipe an umpire line that hasn't started yet but is scheduled first.
      voiceFloor = queue.say(umpPhrase, {
        notBefore: followUpTime,
        priority: PRIORITY.playByPlay,
      });
      voiceFloor = Math.max(voiceFloor, followUpTime + umpireCallDuration(ump)) + 0.12;
    }

    const playExcitement = excitementFor(play);
    if (report.walkOff) {
      crowd.swell(contactTime, 5, 3.2);
    } else if (playExcitement >= 4) {
      crowd.swell(contactTime, playExcitement, play === "home-run" ? 2.6 : 1.2);
    } else if (report.outcome.kind === "strikeout") {
      crowd.swell(followUpTime, 4, 1.0);
    }

    const narration: NarrationContext = {
      pitcher: before.pitcher,
      batter: before.batter,
      batterHand,
      homeTeamName: before.homeTeam,
      awayTeamName: before.awayTeam,
      profile: call.profile,
      location: call.location,
      judgment,
      result: play,
      outcome: report.outcome,
      report,
      after,
      countBefore: { balls: before.balls, strikes: before.strikes },
      countAfter: countAfterFor(before, after, report.outcome),
      spray: clamp(-judgment.deltaMs / 70, -1, 1),
      leverage,
      rng,
    };

    let voiceEnd = queue.say(buildResultCall(narration), {
      notBefore: voiceFloor,
      priority: PRIORITY.playByPlay,
    });

    const colorLine = buildColorLine(narration);
    if (colorLine) {
      voiceEnd = queue.say(colorLine, { notBefore: voiceEnd + 0.3, priority: PRIORITY.color });
    }

    // Bridge fill: count, situation, chess — the sound of baseball on the radio.
    if (!report.gameEnded) {
      for (const bridge of buildBetweenPitchFill(narration)) {
        const priority = bridge.speaker === "color" ? PRIORITY.color : PRIORITY.playByPlay;
        voiceEnd = queue.say(bridge, { notBefore: voiceEnd + 0.35, priority });
      }
    }

    // Between-play "run scores" flourish. Fires on any play that plated a run —
    // hit, sac fly, productive out, or a bases-loaded walk — not just hits.
    if (report.runsScored > 0 && !report.gameEnded) {
      crowd.organStab(voiceEnd + 0.3);
    }

    let challengeOutcome: ChallengeOutcome | null = null;
    if (activeChallenge?.kind === "situation") {
      challengeOutcome = activeChallenge.evaluate({ before, after, report, playerSide });
      if (challengeOutcome && !report.gameEnded && !after.gameOver) {
        state.forceEnd();
      }
    }

    if (report.gameEnded || challengeOutcome) {
      if (activeChallenge?.kind === "situation") {
        const { playerRuns: pr, opponentRuns: or } = {
          playerRuns: after.score[playerSide],
          opponentRuns: after.score[playerSide === "home" ? "away" : "home"],
        };
        const outcome =
          challengeOutcome ??
          ({
            won: pr > or,
            title: pr > or ? "Challenge won!" : "Challenge over",
            summary: activeChallenge.rules,
          } satisfies ChallengeOutcome);
        finishChallenge(outcome, after);
        crowd.organStab(voiceEnd + 1.6, 220);
        return nextGap;
      }
      gameOver = true;
      stopRequested = true;
      clearGameSave();
      const playerRuns = after.score[playerSide];
      const opponentRuns = after.score[playerSide === "home" ? "away" : "home"];
      const won = playerRuns > opponentRuns;
      const tied = playerRuns === opponentRuns;

      let seasonFinished = false;
      let seriesFinished = false;
      let playoffFinished = false;
      let playoffRoundAdvanced = false;
      /** Completed Bo3 shell when a season-of-series slot just clinched (for end-card copy). */
      let seasonSeriesJustWon: SeriesState | null = null;

      if (activePlayoff && !activePlayoff.isComplete()) {
        const beforeRound = activePlayoff.roundIndex;
        playoffFinished = activePlayoff.recordGame(seriesResultFromScore(after.score));
        playoffRoundAdvanced = !playoffFinished && activePlayoff.roundIndex > beforeRound;
        writePlayoff(activePlayoff);
        paintBoard();
      } else if (season && season.unit === "series" && !isSeasonComplete(season)) {
        // Season-of-series: nest Bo3 progress on the season blob (not botn.series.v1).
        const recorded = recordSeasonSeriesGame(season, seriesResultFromScore(after.score));
        season = recorded.season;
        seriesFinished = recorded.seriesFinished;
        seasonFinished = recorded.seasonFinished;
        if (recorded.seriesFinished) seasonSeriesJustWon = recorded.series;
        activeSeries = seasonSeriesState(season);
        writeSeason(season);
        paintBoard();
      } else if (activeSeries && !activeSeries.isComplete()) {
        seriesFinished = activeSeries.recordGame(seriesResultFromScore(after.score));
        writeSeries(activeSeries);
        paintBoard();
      } else if (season && !isSeasonComplete(season)) {
        season = recordSeasonGameResult(season, won ? "win" : tied ? "tie" : "loss");
        writeSeason(season);
        seasonFinished = isSeasonComplete(season);
      }

      window.dispatchEvent(new CustomEvent("baseball-radio-game-over", {
        detail: {
          playerRuns,
          opponentRuns,
          innings: after.inning,
          won,
          durationMs: Math.max(0, Math.round(performance.now() - sessionStartedAt)),
          ...(activePlayoff
            ? {
                playoffRound: activePlayoff.currentRound().id,
                playoffRoundIndex: activePlayoff.roundIndex,
                seriesWins: activePlayoff.series.winsFor(playerSide),
                seriesGames: activePlayoff.series.gamesPlayed,
                seriesBestOf: activePlayoff.series.bestOf,
                playoffComplete: activePlayoff.isComplete(),
              }
            : activeSeries
              ? {
                  seriesWins: activeSeries.winsFor(playerSide),
                  seriesGames: activeSeries.gamesPlayed,
                  seriesBestOf: activeSeries.bestOf,
                }
              : {}),
          ...(season
            ? {
                seasonWins: season.wins,
                seasonLosses: season.losses,
                seasonGames: season.gamesPlayed,
                seasonLength: season.scheduleLength,
                seasonUnit: season.unit ?? "game",
              }
            : {}),
        },
      }));
      const meanTiming = formatMeanTiming();
      const walkOff = Boolean(report.walkOff);

      if (activePlayoff) {
        let spoken: string;
        if (playoffFinished) {
          spoken = activePlayoff.championLine();
        } else if (playoffRoundAdvanced) {
          spoken = activePlayoff.roundTransitionLine();
        } else {
          spoken = activePlayoff.boothBreakLine();
        }
        coachSpeak(spoken, { energy: 0.5 });
        voiceEnd = queue.say(
          {
            id: playoffFinished
              ? "playoff.champion"
              : playoffRoundAdvanced
                ? "playoff.round"
                : "playoff.break",
            text: spoken,
            speaker: "announcer",
            energy: 0.5,
          },
          { notBefore: voiceEnd + 0.35, priority: PRIORITY.playByPlay },
        );
        if (playoffFinished) {
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won: activePlayoff.playerWonPlayoff(),
            walkOff,
            seriesLine: activePlayoff.championLine(),
            seriesFinished: true,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won: activePlayoff.playerWonPlayoff(),
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: activePlayoff.championLine(),
            modeLabel: describeSession(sessionOptions),
            primaryLabel: "New Playoff",
            titleOverride: activePlayoff.playerWonPlayoff()
              ? `${activePlayoff.trophyNoun() === "championship" ? "Championship" : "Pennant"} champions!`
              : `${activePlayoff.trophyNoun() === "championship" ? "Championship" : "Pennant"} over`,
          });
        } else if (playoffRoundAdvanced) {
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won,
            walkOff,
            seriesLine: spoken,
            seriesFinished: false,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won,
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: activePlayoff.scoreLine(),
            modeLabel: spoken,
            primaryLabel: "Next series",
            titleOverride: `On to the ${activePlayoff.currentRound().label}`,
          });
        } else {
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won,
            walkOff,
            seriesLine: activePlayoff.scoreLine(),
            seriesFinished: false,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won,
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: activePlayoff.scoreLine(),
            modeLabel: spoken,
            primaryLabel: "Next game",
            titleOverride: `Game ${activePlayoff.series.gamesPlayed} final`,
          });
        }
      } else if (season && season.unit === "series") {
        const standings = describeSeasonStandings(season);
        const seriesForCard = seasonSeriesJustWon ?? activeSeries;
        if (seasonFinished) {
          const clinch = seasonSeriesJustWon?.resultLine() ?? standings;
          const spoken = `${clinch} ${standings}`;
          coachSpeak(spoken, { energy: 0.5 });
          voiceEnd = queue.say(
            { id: "season.final", text: spoken, speaker: "announcer", energy: 0.5 },
            { notBefore: voiceEnd + 0.35, priority: PRIORITY.playByPlay },
          );
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won,
            walkOff,
            seriesLine: `Final record ${describeSeasonRecordShort(season)}`,
            seriesFinished: true,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won,
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            titleOverride: "Season complete",
            seriesSummary: `Final record ${describeSeasonRecordShort(season)}`,
            modeLabel: describeSession(sessionOptions),
            primaryLabel: "New Season",
          });
          clearSeason();
          season = null;
          activeSeries = null;
        } else if (seriesFinished && seriesForCard) {
          const spoken = `${seriesForCard.resultLine()} ${standings}`;
          coachSpeak(spoken, { energy: 0.5 });
          voiceEnd = queue.say(
            { id: "season.series", text: spoken, speaker: "announcer", energy: 0.5 },
            { notBefore: voiceEnd + 0.35, priority: PRIORITY.playByPlay },
          );
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won: seriesForCard.playerWonSeries(),
            walkOff,
            seriesLine: spoken,
            seriesFinished: true,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won: seriesForCard.playerWonSeries(),
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: standings,
            modeLabel: `${describeSeasonGameSlot(season)} up next.`,
            primaryLabel: "Next series",
            titleOverride: seriesForCard.playerWonSeries() ? "Series win!" : "Series over",
          });
        } else if (seriesForCard) {
          const seriesLine = seriesForCard.boothBreakLine();
          const spoken = `${seriesLine} ${standings}`;
          coachSpeak(spoken, { energy: 0.5 });
          voiceEnd = queue.say(
            { id: "season.series.break", text: spoken, speaker: "announcer", energy: 0.5 },
            { notBefore: voiceEnd + 0.35, priority: PRIORITY.playByPlay },
          );
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won,
            walkOff,
            seriesLine: spoken,
            seriesFinished: false,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won,
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: seriesForCard.scoreLine(),
            modeLabel: spoken,
            primaryLabel: "Next game",
            titleOverride: `Game ${seriesForCard.gamesPlayed} final`,
          });
        }
      } else if (activeSeries) {
        const seriesLine = seriesFinished ? activeSeries.resultLine() : activeSeries.boothBreakLine();
        coachSpeak(seriesLine, { energy: 0.5 });
        voiceEnd = queue.say(
          { id: seriesFinished ? "series.final" : "series.break", text: seriesLine, speaker: "announcer", energy: 0.5 },
          { notBefore: voiceEnd + 0.35, priority: PRIORITY.playByPlay },
        );
        if (seriesFinished) {
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won: activeSeries.playerWonSeries(),
            walkOff,
            seriesLine: activeSeries.resultLine(),
            seriesFinished: true,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won: activeSeries.playerWonSeries(),
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: activeSeries.resultLine(),
            modeLabel: describeSession(sessionOptions),
            primaryLabel: "New Series",
            titleOverride: activeSeries.playerWonSeries() ? "Series win!" : "Series over",
          });
        } else {
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won,
            walkOff,
            seriesLine: activeSeries.scoreLine(),
            seriesFinished: false,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won,
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: activeSeries.scoreLine(),
            modeLabel: seriesLine,
            primaryLabel: "Next game",
            titleOverride: `Game ${activeSeries.gamesPlayed} final`,
          });
        }
      } else if (season) {
        const standings = describeSeasonStandings(season);
        coachSpeak(standings, { energy: 0.5 });
        if (seasonFinished) {
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won,
            walkOff,
            seriesLine: `Final record ${describeSeasonRecordShort(season)}`,
            seriesFinished: true,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won,
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            titleOverride: "Season complete",
            seriesSummary: `Final record ${describeSeasonRecordShort(season)}`,
            modeLabel: describeSession(sessionOptions),
            primaryLabel: "New Season",
          });
          clearSeason();
          season = null;
        } else {
          const nextLine = `We'll be right back for ${describeSeasonGameSlot(season).toLowerCase()}. ${standings}`;
          coachSpeak(nextLine, { energy: 0.45 });
          captureShareMoment({
            playerRuns,
            opponentRuns,
            innings: after.inning,
            won,
            walkOff,
            seriesLine: standings,
            seriesFinished: false,
            modeLabel: describeSession(sessionOptions),
          });
          endGameCard.show({
            won,
            playerRuns,
            opponentRuns,
            innings: after.inning,
            timingSummary: meanTiming,
            seriesSummary: standings,
            modeLabel: `${describeSeasonGameSlot(season)} up next.`,
            primaryLabel: "Next game",
          });
        }
      } else {
        captureShareMoment({
          playerRuns,
          opponentRuns,
          innings: after.inning,
          won,
          walkOff,
          modeLabel: describeSession(sessionOptions),
        });
        endGameCard.show({
          won,
          playerRuns,
          opponentRuns,
          innings: after.inning,
          timingSummary: meanTiming,
          modeLabel: describeSession(sessionOptions),
        });
      }
      const gameOverCall = buildGameOverCall(report, after, before.batter, before.homeTeam, before.awayTeam, rng);
      queue.say(gameOverCall, { notBefore: voiceEnd + 0.4, priority: PRIORITY.playByPlay });
      crowd.organStab(voiceEnd + 1.6, 220);
    } else if (report.inningEnded) {
      const breakCall = buildInningBreakCall(before, after, before.homeTeam, before.awayTeam, rng);
      voiceEnd = queue.say(breakCall, { notBefore: voiceEnd + INNING_BREAK_SEC, priority: PRIORITY.playByPlay });
      voiceEnd = queue.say(buildStationIdLine(rng), {
        notBefore: voiceEnd + 0.25,
        priority: PRIORITY.utility,
      });
      crowd.organStab(voiceEnd + 0.6, 329.63);
      crowd.setExcitement(currentExcitement(after), 2.0);
      nextGap = BETWEEN_PITCHES_SEC + 2.5;
    } else {
      crowd.setExcitement(currentExcitement(after), 2.0);
    }

    // Occasional Eric vendor line during a lull — queue so it yields to the booth.
    pitchesSinceVendor++;
    if (
      !report.gameEnded &&
      !report.inningEnded &&
      report.runsScored === 0 &&
      leverage < 1.2 &&
      pitchesSinceVendor >= 4 &&
      rng() < 0.22
    ) {
      pitchesSinceVendor = 0;
      const roll = rng();
      const kind: "dogs" | "beer" | "programs" =
        roll < 0.45 ? "dogs" : roll < 0.75 ? "beer" : "programs";
      queue.say(buildVendorLine(rng, kind), {
        notBefore: voiceEnd + 0.55,
        priority: PRIORITY.utility,
      });
    }

    return nextGap;
  }
}

/**
 * The count as it stood when the announcer describes the pitch.
 *
 * `GameState` zeroes the count the moment a plate appearance ends, but the call
 * still has to say "ball four" or "strike three" — so for a terminal pitch we
 * reconstruct the count that pitch produced rather than reading the fresh one.
 */
function countAfterFor(
  before: { balls: number; strikes: number },
  after: { balls: number; strikes: number },
  outcome: PlateOutcome,
): { balls: number; strikes: number } {
  switch (outcome.kind) {
    case "walk":
      return { balls: 4, strikes: before.strikes };
    case "strikeout":
      return { balls: before.balls, strikes: 3 };
    case "out":
    case "hit":
      return before;
    case "pitch":
      return after;
  }
}

function umpireCallFor(play: PlayResult, outcome: PlateOutcome): UmpireCall | null {
  if (outcome.kind === "strikeout") return "strike-three";
  switch (play) {
    case "called-strike":
      return "strike";
    case "ball":
      return "ball";
    case "foul-ball":
      return "foul";
    case "line-out":
    case "fly-out":
    case "ground-out":
    case "pop-up":
      return "out";
    // A swing and miss needs no announcement — everyone heard it.
    default:
      return null;
  }
}

function clampLevel(value: number): ExcitementLevel {
  return Math.min(5, Math.max(1, Math.round(value))) as ExcitementLevel;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function ordinal(value: number): string {
  const mod100 = value % 100;
  if (mod100 >= 11 && mod100 <= 13) return "th";
  switch (value % 10) {
    case 1: return "st";
    case 2: return "nd";
    case 3: return "rd";
    default: return "th";
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function waitForIdle(predicate: () => boolean): Promise<void> {
  return new Promise((resolve) => {
    const poll = setInterval(() => {
      if (!predicate()) return;
      clearInterval(poll);
      resolve();
    }, 30);
  });
}
