import type { Speaker } from "./VoiceBackend.ts";

/**
 * Shared Web Speech helpers for the booth and the umpire.
 *
 * This path is outside the Web Audio graph — it cannot ride the AM bandpass or
 * share a bus with the field — but it is the only asset-free way to produce
 * words a listener can actually understand. Crowd ducking still runs from the
 * VoiceBackend clock; the field bus is left alone so pitch cues stay clear.
 *
 * Booth lines enqueue without cancelling (so pxp/color don't truncate each other).
 * Coaching cues and UI announces pass `interrupt: true` to take the mic now.
 */

export interface SpeakRequest {
  text: string;
  speaker: Speaker;
  energy: number;
  /**
   * When true (default), stop anything currently speaking/queued and talk now.
   * When false, append to the speechSynthesis queue so the previous sentence finishes.
   */
  interrupt?: boolean;
  /** Called if this utterance was interrupted or finished. */
  onEnded?: () => void;
}

interface PendingUtterance {
  cancelled: boolean;
}

let voicesReady: Promise<void> | null = null;
let nextToken = 0;
const pending = new Map<number, PendingUtterance>();
/** Global multiplier applied in applyVoice (a11y speech-rate pref). */
let speechRateMultiplier = 1;

/** 0.7–1.4 typical; 1 is the stock booth pace. */
export function setSpeechRateMultiplier(value: number): void {
  speechRateMultiplier = Number.isFinite(value) ? Math.min(1.4, Math.max(0.7, value)) : 1;
}

export function getSpeechRateMultiplier(): number {
  return speechRateMultiplier;
}

/** Prime the speech engine inside a user gesture so the first real call isn't dropped. */
export function warmUpSpeech(): void {
  if (typeof speechSynthesis === "undefined") return;
  ensureVoices();
  // A zero-volume utterance unlocks the engine on Chromium after a gesture.
  const warm = new SpeechSynthesisUtterance(" ");
  warm.volume = 0;
  warm.rate = 2;
  speechSynthesis.speak(warm);
  speechSynthesis.cancel();
}

export function ensureVoices(): Promise<void> {
  if (typeof speechSynthesis === "undefined") return Promise.resolve();
  if (voicesReady) return voicesReady;

  const existing = speechSynthesis.getVoices();
  if (existing.length > 0) {
    voicesReady = Promise.resolve();
    return voicesReady;
  }

  voicesReady = new Promise((resolve) => {
    const done = (): void => {
      speechSynthesis.removeEventListener("voiceschanged", done);
      resolve();
    };
    speechSynthesis.addEventListener("voiceschanged", done);
    // Safari sometimes never fires voiceschanged if the list is already cached empty.
    window.setTimeout(done, 750);
  });
  return voicesReady;
}

/**
 * Speak `request`. Returns a token so the caller can cancel only its own utterance
 * before it has been handed to the engine.
 */
export function speakNow(request: SpeakRequest): number {
  if (typeof speechSynthesis === "undefined") {
    request.onEnded?.();
    return -1;
  }

  const interrupt = request.interrupt !== false;
  if (interrupt) {
    for (const entry of pending.values()) entry.cancelled = true;
    pending.clear();
    speechSynthesis.cancel();
  }

  const token = ++nextToken;
  pending.set(token, { cancelled: false });

  const utterance = new SpeechSynthesisUtterance(forSpeech(request.text));
  applyVoice(utterance, request.speaker, request.energy);

  const finish = (): void => {
    pending.delete(token);
    request.onEnded?.();
  };
  utterance.onend = finish;
  utterance.onerror = finish;

  void ensureVoices().then(() => {
    const entry = pending.get(token);
    if (!entry || entry.cancelled) return;
    // Re-apply after voices load — the first call often races an empty list.
    applyVoice(utterance, request.speaker, request.energy);
    speechSynthesis.speak(utterance);
  });

  return token;
}

/** Cancel only if `token` has not yet been handed to the engine / already finished. */
export function cancelSpeech(token: number): void {
  if (token < 0) return;
  const entry = pending.get(token);
  if (!entry) return;
  entry.cancelled = true;
  pending.delete(token);
  // Surgical removal from the browser TTS queue is not supported. Pause/teardown
  // uses cancelAllSpeech; undelivered booth lines are stopped via clearTimeout
  // before speakNow runs.
}

/** Cancel whatever is speaking or queued, regardless of owner. */
export function cancelAllSpeech(): void {
  for (const entry of pending.values()) entry.cancelled = true;
  pending.clear();
  if (typeof speechSynthesis !== "undefined") speechSynthesis.cancel();
}

function applyVoice(utterance: SpeechSynthesisUtterance, speaker: Speaker, energy: number): void {
  const voice = pickVoice(speaker);
  if (voice) utterance.voice = voice;

  // Keep rates in the intelligible band. Excited ≠ unintelligible.
  let rate: number;
  if (speaker === "umpire") {
    rate = 1.05;
    utterance.pitch = 0.85;
    utterance.volume = 1;
  } else if (speaker === "color") {
    rate = 0.98;
    utterance.pitch = 0.92; // keep OS fallback in Brian's deeper lane, not bright/female
    utterance.volume = 1;
  } else if (speaker === "utility") {
    rate = 1.02;
    utterance.pitch = 1.0;
    utterance.volume = 0.95;
  } else {
    rate = 1.02 + clamp01(energy) * 0.12;
    utterance.pitch = 0.95;
    utterance.volume = 1;
  }
  utterance.rate = Math.min(1.6, Math.max(0.6, rate * speechRateMultiplier));
}

const FEMALE_VOICE =
  /female|zira|samantha|hazel|susan|linda|jenny|aria|jane|karen|moira|tessa|fiona|victoria|susan|heather|allison|ava|emma|joanna|kendra|kimberly|salli|ivy|nicole|raveena|aditi|amy|emma|geraint|female/i;

function pickVoice(speaker: Speaker): SpeechSynthesisVoice | null {
  if (typeof speechSynthesis === "undefined") return null;
  const voices = speechSynthesis.getVoices();
  if (voices.length === 0) return null;

  const english = voices.filter((v) => /^en(-|_)/i.test(v.lang) || /english/i.test(v.name));
  const base = english.length > 0 ? english : voices;
  // Booth cast is all male (Adam / Brian / Eric). Never hand color/PBP to a female OS voice.
  const malePool = base.filter((v) => !FEMALE_VOICE.test(v.name));
  const pool = malePool.length > 0 ? malePool : base;

  if (speaker === "umpire") {
    return (
      prefer(pool, [/david/i, /guy/i, /aaron/i, /mark/i, /george/i, /male/i]) ??
      pool[0] ??
      null
    );
  }
  if (speaker === "color") {
    // Brian stand-in for gaps — deep male only (old prefs wrongly preferred Samantha/Zira).
    return (
      prefer(pool, [/daniel/i, /james/i, /brian/i, /george/i, /david/i, /mark/i, /guy/i, /male/i]) ??
      pool[Math.min(1, pool.length - 1)] ??
      null
    );
  }
  if (speaker === "utility") {
    return (
      prefer(pool, [/eric/i, /ryan/i, /chris/i, /mark/i, /david/i, /male/i]) ??
      pool[Math.min(2, pool.length - 1)] ??
      null
    );
  }
  // Adam stand-in for play-by-play gaps.
  return (
    prefer(pool, [/david/i, /mark/i, /guy/i, /microsoft david/i, /google us english/i, /male/i]) ??
    pool[0] ??
    null
  );
}

function prefer(
  voices: SpeechSynthesisVoice[],
  patterns: RegExp[],
): SpeechSynthesisVoice | null {
  for (const pattern of patterns) {
    const hit = voices.find((v) => pattern.test(v.name));
    if (hit) return hit;
  }
  return null;
}

/** TTS reads punctuation badly — turn broadcast dashes into pauses. */
export function forSpeech(text: string): string {
  return text
    .replace(/[—–]/g, ", ")
    .replace(/\s+/g, " ")
    .replace(/\s+,/g, ",")
    .trim();
}

function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}
