import type { GameSnapshot } from "./GameState.ts";
import { AWAY_TEAM, HOME_TEAM, type Team } from "./Teams.ts";

/**
 * PlayerSide — which club the human controls.
 *
 * Home bats in the bottom and pitches in the top; away is the reverse.
 */

export type PlayerSide = "home" | "away";

const STORAGE_KEY = "botn.side";

export function isPlayerSide(value: string): value is PlayerSide {
  return value === "home" || value === "away";
}

export function loadPlayerSide(): PlayerSide {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw && isPlayerSide(raw)) return raw;
  } catch {
    // private mode / blocked storage
  }
  return "home";
}

export function savePlayerSide(side: PlayerSide): void {
  try {
    localStorage.setItem(STORAGE_KEY, side);
  } catch {
    // ignore
  }
}

export function teamForSide(side: PlayerSide): Team {
  return side === "home" ? HOME_TEAM : AWAY_TEAM;
}

export function isPlayerBatting(snapshot: GameSnapshot, side: PlayerSide): boolean {
  const team = teamForSide(side);
  return snapshot.battingTeam === team.shortName;
}

export function announcePlayerSide(side: PlayerSide): string {
  const team = teamForSide(side);
  if (side === "home") {
    return `You're the ${team.shortName}. Bat in the bottom, pitch in the top.`;
  }
  return `You're the ${team.shortName}. Bat in the top, pitch in the bottom.`;
}

export function roleAnnounce(isBatting: boolean): string {
  return isBatting ? "Now batting." : "Now pitching.";
}
