/**
 * ClockBridge — correlates the Web Audio clock with the DOM performance clock.
 *
 * Why this exists
 * ---------------
 * Audio is scheduled on `AudioContext.currentTime` (seconds, audio-device clock).
 * Input arrives on the `performance.now()` timeline (milliseconds, wall clock).
 * The two run at slightly different rates and are separated by an output latency
 * that varies from ~5 ms (wired, small buffer) to ~300 ms (Bluetooth).
 *
 * Comparing them naively — remembering `currentTime` when a pitch is scheduled and
 * diffing it against `performance.now()` at keydown — produces errors an order of
 * magnitude larger than the 30 ms "perfect contact" window. The game feels broken
 * and nothing in the code looks wrong. Hence this module.
 *
 * How it works
 * ------------
 * We maintain a single scalar, `offsetMs`, defined as:
 *
 *     offsetMs = performanceTime_ms - contextTime_s * 1000
 *
 * Given that, conversion in both directions is arithmetic. The whole problem is
 * measuring `offsetMs` accurately and keeping it fresh.
 *
 * Preferred source is `AudioContext.getOutputTimestamp()`, which returns a
 * {contextTime, performanceTime} pair describing the same physical instant *at the
 * output device*. Per spec, `contextTime` is the frame currently being played —
 * i.e. it already accounts for output latency, so no further correction is needed.
 *
 * Fallback, for engines where that method is missing or returns a useless
 * `performanceTime` of 0 (older Firefox) — pair `performance.now()` with
 * `currentTime` read back-to-back, then add the reported output latency by hand.
 * Safari historically does not implement `outputLatency`, so we degrade to
 * `baseLatency` and finally to a 20 ms guess.
 *
 * Both paths are noisy: `currentTime` advances in render quanta (128 frames ≈ 2.7 ms
 * at 48 kHz) and the sampling callback is subject to main-thread jitter. We keep a
 * short window of samples and take the median, which rejects outliers far better
 * than a mean and costs nothing at this size.
 */

/** The slice of `AudioContext` this module needs. Structural, so tests can fake it. */
export interface ClockSource {
  readonly currentTime: number;
  readonly baseLatency?: number | undefined;
  readonly outputLatency?: number | undefined;
  getOutputTimestamp?(): { contextTime?: number; performanceTime?: number };
}

export type OffsetSource = "output-timestamp" | "sampled" | "uninitialized";

export interface ClockBridgeStats {
  /** performanceTime(ms) - contextTime(s)*1000, median of the current window. */
  offsetMs: number;
  /** Spread (max - min) across the window. High values mean an unreliable estimate. */
  jitterMs: number;
  /** Which measurement path produced the current offset. */
  source: OffsetSource;
  /** Output latency in ms, as reported by the engine (0 if unavailable). */
  reportedLatencyMs: number;
  sampleCount: number;
}

export interface ClockBridgeOptions {
  /** Samples retained for the median. Larger = steadier but slower to follow a device change. */
  windowSize?: number;
  /** Used only when neither outputLatency nor baseLatency is available. */
  fallbackLatencySec?: number;
  /**
   * A new sample this far from the running median is treated as a discontinuity
   * (context resumed, output device switched) rather than noise: the window is
   * dropped and re-seeded from the new value.
   */
  resyncThresholdMs?: number;
  /** Injectable clock, for tests. */
  now?: () => number;
}

const DEFAULTS = {
  windowSize: 15,
  fallbackLatencySec: 0.02,
  resyncThresholdMs: 250,
} as const;

export class ClockBridge {
  private readonly ctx: ClockSource;
  private readonly now: () => number;
  private readonly windowSize: number;
  private readonly fallbackLatencySec: number;
  private readonly resyncThresholdMs: number;

  private samples: number[] = [];
  private medianCache: number | null = null;
  private source: OffsetSource = "uninitialized";
  private reportedLatencySec = 0;
  private rafHandle: number | null = null;
  private intervalHandle: ReturnType<typeof setInterval> | null = null;

  constructor(ctx: ClockSource, options: ClockBridgeOptions = {}) {
    this.ctx = ctx;
    this.now = options.now ?? (() => performance.now());
    this.windowSize = options.windowSize ?? DEFAULTS.windowSize;
    this.fallbackLatencySec = options.fallbackLatencySec ?? DEFAULTS.fallbackLatencySec;
    this.resyncThresholdMs = options.resyncThresholdMs ?? DEFAULTS.resyncThresholdMs;
    this.sample();
  }

  /**
   * Take one correlation reading. Cheap — safe to call every animation frame.
   * Call it at least a few times before trusting `audioToPerf`.
   */
  sample(): void {
    const measured = this.measureOffset();
    if (measured === null) return;

    // A jump this large is a real event (resume, device change), not jitter.
    // Following it slowly would leave every swing mis-judged for a second or two.
    const current = this.medianCache;
    if (current !== null && Math.abs(measured - current) > this.resyncThresholdMs) {
      this.samples = [];
    }

    this.samples.push(measured);
    if (this.samples.length > this.windowSize) this.samples.shift();
    this.medianCache = median(this.samples);
  }

  /**
   * Read one offset candidate, preferring the output-timestamp path.
   * Returns null when no usable reading is available yet.
   */
  private measureOffset(): number | null {
    const stamped = this.readOutputTimestamp();
    if (stamped !== null) {
      this.source = "output-timestamp";
      return stamped;
    }

    // Fallback: correlate by hand. Read the wall clock on both sides of the audio
    // clock read and take the midpoint, so the cost of the property access itself
    // doesn't bias the result in one direction.
    const before = this.now();
    const contextTime = this.ctx.currentTime;
    const after = this.now();
    const perfTime = (before + after) / 2;

    this.reportedLatencySec = this.resolveLatencySec();
    this.source = "sampled";
    return perfTime - contextTime * 1000 + this.reportedLatencySec * 1000;
  }

  private readOutputTimestamp(): number | null {
    if (typeof this.ctx.getOutputTimestamp !== "function") return null;

    let ts: { contextTime?: number; performanceTime?: number } | undefined;
    try {
      ts = this.ctx.getOutputTimestamp();
    } catch {
      return null; // Some engines throw while the context is still suspended.
    }
    if (!ts) return null;

    const { contextTime, performanceTime } = ts;
    if (typeof contextTime !== "number" || typeof performanceTime !== "number") return null;
    if (!Number.isFinite(contextTime) || !Number.isFinite(performanceTime)) return null;

    // Firefox historically returned performanceTime === 0. A genuine 0 only occurs
    // in the first frame after page load, which is not a moment we care about.
    if (performanceTime <= 0) return null;

    // contextTime here is already the presentation time at the device, so the
    // latency is baked in. Report it separately for diagnostics only.
    this.reportedLatencySec = this.resolveLatencySec();
    return performanceTime - contextTime * 1000;
  }

  private resolveLatencySec(): number {
    const output = this.ctx.outputLatency;
    if (typeof output === "number" && Number.isFinite(output) && output > 0) return output;
    const base = this.ctx.baseLatency;
    if (typeof base === "number" && Number.isFinite(base) && base > 0) return base;
    return this.fallbackLatencySec;
  }

  /**
   * Convert a scheduled audio-clock time (seconds) into the wall-clock instant
   * (performance-timeline ms) at which the listener will actually hear it.
   */
  audioToPerf(contextTimeSec: number): number {
    return contextTimeSec * 1000 + this.offsetMs;
  }

  /** Inverse of {@link audioToPerf}: wall-clock ms to audio-clock seconds. */
  perfToAudio(performanceTimeMs: number): number {
    return (performanceTimeMs - this.offsetMs) / 1000;
  }

  /** Current best estimate of the clock offset, in milliseconds. */
  get offsetMs(): number {
    if (this.medianCache !== null) return this.medianCache;
    // Nothing sampled successfully yet — fall back to an instantaneous read so
    // callers always get a usable number rather than NaN.
    const before = this.now();
    const contextTime = this.ctx.currentTime;
    return before - contextTime * 1000 + this.resolveLatencySec() * 1000;
  }

  /** True once enough samples have accumulated for the median to mean something. */
  get isReady(): boolean {
    return this.samples.length >= Math.min(5, this.windowSize);
  }

  stats(): ClockBridgeStats {
    const jitter =
      this.samples.length > 1 ? Math.max(...this.samples) - Math.min(...this.samples) : 0;
    return {
      offsetMs: this.offsetMs,
      jitterMs: jitter,
      source: this.source,
      reportedLatencyMs: this.reportedLatencySec * 1000,
      sampleCount: this.samples.length,
    };
  }

  /**
   * Drop all history. Call after resuming a suspended context — `currentTime`
   * stops advancing while suspended, so every retained sample is stale.
   */
  reset(): void {
    this.samples = [];
    this.medianCache = null;
    this.sample();
  }

  /** Begin sampling automatically. Uses rAF where available, a timer otherwise. */
  startAutoSampling(): void {
    if (this.rafHandle !== null || this.intervalHandle !== null) return;

    const raf = globalThis.requestAnimationFrame;
    if (typeof raf === "function") {
      const tick = (): void => {
        this.sample();
        this.rafHandle = raf(tick);
      };
      this.rafHandle = raf(tick);
      return;
    }
    this.intervalHandle = setInterval(() => this.sample(), 250);
  }

  stopAutoSampling(): void {
    if (this.rafHandle !== null) {
      globalThis.cancelAnimationFrame?.(this.rafHandle);
      this.rafHandle = null;
    }
    if (this.intervalHandle !== null) {
      clearInterval(this.intervalHandle);
      this.intervalHandle = null;
    }
  }
}

function median(values: readonly number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = sorted.length >> 1;
  if (sorted.length % 2 === 1) return sorted[mid] as number;
  return ((sorted[mid - 1] as number) + (sorted[mid] as number)) / 2;
}
